window.__Q=window.__Q||{};window.__Q["tcm/4/A2"]=[{"q":"患者腰痛脚软，身半以下常有冷感，少腹拘急，小便不利或小便反多，入夜尤甚，阳痿早泄，舌淡而胖，脉虚弱，尺脉沉细，以及痰饮，水肿，消渴，脚气，转胞等，治疗宜用的方剂是","o":["左归丸","右归丸","大补阴丸","肾气丸","六味地黄丸"],"a":3,"e":"证属肾阳不足、气化失职。肾气丸以六味地黄滋补肾阴，少佐桂枝、附子温阳化气，取阴中求阳之义，为温补肾阳、化气行水的基础方。"},{"q":"患者肢体沉重，怠惰嗜卧，脘腹胀满，舌苔白腻，脉缓。治疗应首选的治法是","o":["燥湿和胃，消痞除满","健脾和胃，行气除满","益气健脾，行气导滞","燥湿运脾，行气和胃","燥湿健脾，和胃止呕"],"a":3,"e":"湿浊困阻中焦，气机不畅。平胃散以苍术燥湿运脾为君，厚朴、陈皮行气化湿，甘草、姜、枣和中，故治法为燥湿运脾、行气和胃。"},{"q":"患者面目俱黄，黄色鲜明，发热口渴，恶心呕吐，脘腹微满，小便短赤，舌苔黄腻，脉滑数有力。治疗应首选的方剂是","o":["甘露消毒丹","栀子柏皮汤","茵陈蒿汤","茵陈四逆汤","三仁汤"],"a":2,"e":"湿热内蕴，热重于湿，胆汁外溢肌肤。茵陈蒿汤以茵陈为退黄要药，配栀子清利三焦湿热，大黄泻热逐瘀、通利大便，使湿热从二便分消。"},{"q":"患者瘟疫热毒，气血两燔证而见四肢抽搐，发斑疹，舌绛唇焦，脉沉细数。治疗应首选的方剂是","o":["清瘟败毒饮","黄连解毒汤","竹叶石膏汤","犀角地黄汤","普济消毒饮"],"a":0,"e":"瘟疫热毒充斥，气血两燔。清瘟败毒饮合白虎汤、犀角地黄汤、黄连解毒汤三方之长，气血两清兼凉血散血，故抽搐发斑、舌绛唇焦者宜之。"},{"q":"患者心热移于小肠，小便赤涩刺痛，舌红脉数。治疗应首选的方剂是","o":["玉女煎","导赤散","猪苓汤","五苓散","八正散"],"a":1,"e":"心热移于小肠，治当清心利水养阴。导赤散以木通、竹叶清心降火利水，生地凉血滋阴，甘草梢直达茎中止淋痛，使心火从小便而去。"},{"q":"患者，男，65岁。腹痛便秘，手足不温，苔白腻，脉弦紧。下列最为适宜选用的方剂是","o":["大承气汤","大黄附子汤","小承气汤","调胃承气汤","济川煎"],"a":1,"e":"寒积里实，阳气不运。大黄附子汤以附子、细辛温散寒凝，大黄泻下通便，温下并用，使冷积去而阳气不伤，为温下剂之范例。"},{"q":"患者脘腹疼痛，喜温欲按，自利不渴，畏寒肢冷，呕吐，不欲饮食，舌淡苔白，脉沉细。辨证为脾胃虚寒证。方剂宜选用","o":["吴茱萸汤","小建中汤","大建中汤","理中丸","四逆汤"],"a":3,"e":"脾胃虚寒，中阳不振。理中丸以干姜温中祛寒为君，人参、白术、甘草益气健脾，温补并行，使中阳复而运化健，腹痛自利者宜之。"},{"q":"患者恶寒发热，无汗，头痛，鼻塞，咳嗽痰白，胸脘满闷，倦怠无力，气短懒言，舌苔白，脉弱。治疗当首选的方剂是","o":["小青龙汤","止嗽散","败毒散","再造散","参苏饮"],"a":4,"e":"气虚外感风寒，内有痰湿。参苏饮以苏叶、葛根解表，人参益气，二陈汤化痰理气，枳壳、桔梗宣降气机，为气虚感冒兼痰湿之常用方。"},{"q":"小蓟饮子的组成药物中无","o":["生地黄","大黄","淡竹叶","蒲黄","山栀子"],"a":1,"e":"小蓟饮子由小蓟、生地、蒲黄、藕节、滑石、木通、淡竹叶、山栀子、当归、甘草组成，功在凉血止血、利水通淋，方中并无大黄。"},{"q":"症见两胁作痛，头痛目眩，口燥咽干，神疲食少，月经不调，乳房胀痛，脉虚而弦者，首选治疗方剂是","o":["归脾汤","龙胆泻肝汤","柴胡疏肝散","温经汤","逍遥散"],"a":4,"e":"肝郁血虚，脾失健运。逍遥散以柴胡疏肝解郁，当归、白芍养血柔肝，白术、茯苓、甘草健脾，少佐薄荷、煨姜，肝脾同调，为调和肝脾之名方。"},{"q":"患者正值夏月感寒，刻诊见恶寒发热，头疼身痛，腹痛吐泻，胸脘痞闷，舌苔白腻，脉浮，临床辨证为","o":["暑湿证","阳暑","阴暑","暑温证","湿温证"],"a":2,"e":"夏月乘凉饮冷，外感风寒而内伤湿滞，属阴暑。香薷散以香薷解表散寒、祛暑化湿，厚朴行气除满，白扁豆健脾和中。"},{"q":"以恶寒发热，无汗而喘，脉浮紧为辨证要点的方剂是","o":["桂枝汤","小青龙汤","麻黄汤","大青龙汤","败毒散"],"a":2,"e":"外感风寒表实证。麻黄汤以麻黄发汗解表、宣肺平喘为君，桂枝助其发汗，杏仁降肺气，甘草调和，故以无汗而喘、脉浮紧为要点。"},{"q":"患者膈下瘀阻气滞，形成痞块，痛处不移，卧则腹坠。治疗应首选的方剂是","o":["失笑散","血府逐瘀汤","桃核承气汤","复元活血汤","膈下逐瘀汤"],"a":4,"e":"膈下瘀血阻滞，气机不畅。膈下逐瘀汤以桃仁、红花、当归、川芎活血化瘀，香附、乌药、枳壳行气，专治膈下瘀阻成块、痛处不移者。"},{"q":"患者，女，66岁。有慢性胃炎病史，现主要症状体征有：胃脘疼痛，手足不温，喜食热食，大便溏泄，四肢无力，嗜卧，舌淡苔白，脉沉。宜选择下列哪方治疗","o":["理中丸","小建中汤","桂枝人参汤","阳和汤","四逆汤"],"a":0,"e":"中焦虚寒，运化失职。理中丸温中祛寒、补气健脾，干姜配参、术，寒湿去而中阳复，故胃痛喜温、便溏肢冷者宜之。"},{"q":"患者反复自汗出，夜卧尤甚，心悸惊惕，气短烦倦，舌嫩红，脉细弱者。治宜选用","o":["桂枝汤","牡蛎散","玉屏风散","当归六黄汤","酸枣仁汤"],"a":1,"e":"表虚不固，阴液外泄。牡蛎散以煅牡蛎敛汗固表为君，黄芪益气实卫，麻黄根专于止汗，浮小麦养心敛液，汗出夜甚、心悸气短者用之。"},{"q":"患者身热口渴，咽痛颐肿，小便短赤，或泄泻淋浊，舌苔黄腻，脉濡数。治疗应首选的治法是","o":["利湿化浊，清热凉血","利湿化浊，清热泻火","利湿化浊，清热解毒","利尿通淋，清热解毒","祛风除湿，清热解毒"],"a":2,"e":"湿温时疫，湿热并重。甘露消毒丹以滑石、茵陈、黄芩清利湿热，石菖蒲、藿香、白蔻仁芳化湿浊，薄荷、连翘透热于外，故能利湿化浊、清热解毒。"},{"q":"症见肠鸣腹痛，大便泄泻，泻必腹痛，泻后痛缓，舌苔薄白，脉两关不调，左弦而右缓者，首选治疗方剂是","o":["理中丸","参苓白术散","归脾汤","痛泻要方","逍遥散"],"a":3,"e":"肝脾不和，脾虚肝旺。痛泻要方以白术健脾燥湿，白芍柔肝缓急，防风散肝舒脾，陈皮理气醒脾，泻后痛减为其审证要点。"},{"q":"患者，男，58岁。有慢支炎病史。因气温突降，受凉感冒2天，现恶寒发热，无汗，头身疼痛，喘咳，痰多清稀，晚上不能平卧，舌苔白滑，脉浮。可用下列何方加味治疗","o":["败毒散","九味羌活汤","小青龙汤","香苏散","葱豉桔梗汤"],"a":2,"e":"外感风寒，内停水饮。小青龙汤以麻黄、桂枝解表散寒，干姜、细辛、半夏温肺化饮，五味子、白芍敛肺护阴，散收并用，为外寒内饮之要方。"},{"q":"患者身热夜甚，神烦少寐，斑疹隐隐，舌绛而干，脉细数。治疗应首选的方剂是","o":["清营汤","竹叶石膏汤","清暑益气汤","青蒿鳖甲汤","白虎加人参汤"],"a":0,"e":"热入营分，营阴受损。清营汤以犀角、生地、玄参、麦冬清营解毒、养阴生津，金银花、连翘、竹叶透热转气，丹参凉血散瘀，使营热透转气分而解。"},{"q":"患者口眼斜，舌强不能言语，手足不能运动，风邪散见，不拘一经。治疗首选的方剂是","o":["大秦艽汤","小活络丹","镇肝熄风汤","地黄饮子","牵正散"],"a":0,"e":"风邪初中经络，气血痹阻。大秦艽汤以秦艽祛风通络，羌活、独活、防风散风，当归、川芎、白芍养血活血，石膏、黄芩清里热，风邪散见不拘一经者宜之。"},{"q":"患者适逢暑日，乘凉饮冷，症见恶寒发热，头疼身痛，腹痛吐泻，胸脘痞闷，舌苔白腻，脉浮。此病证的治法是","o":["清暑益气，养阴生津","祛暑解表，化湿和中","疏风清热，宣肺止咳","清热生津，益气和胃","清暑利湿"],"a":1,"e":"夏月感寒，外寒内湿。香薷散以香薷解表祛暑、化湿和中，厚朴行气除满，扁豆健脾化湿，故治法为祛暑解表、化湿和中。"},{"q":"患者胸胁满闷，头晕目眩，背部恶寒，晨起吐清涎，舌苔白滑，脉弦滑。治疗应首选的方剂是","o":["十枣汤","苓桂术甘汤","龙胆泻肝汤","柴胡疏肝散","苏子降气汤"],"a":1,"e":"中阳不足，饮停心下。苓桂术甘汤以茯苓健脾渗湿为君，桂枝温阳化气，白术健脾燥湿，甘草和中，温阳化饮，为治痰饮之基础方。"},{"q":"患者面色㿠白，身热自汗，大便稀溏，气短乏力，舌质淡，脉大而虚软，治宜选用","o":["玉屏风散","四君子汤","参苓白术散","补中益气汤","八珍汤"],"a":3,"e":"脾胃气虚，清阳下陷，阴火内生。补中益气汤以黄芪补中益气、升阳固表为君，参、术、草健脾，升麻、柴胡升举清阳，气虚发热者宜之。"},{"q":"妇人经期经停不至，少腹里急，腹满，傍晚发热，手心烦热，唇口干燥，舌质黯红，脉细而涩。治疗应首选的方剂是","o":["温经汤","桂枝茯苓丸","血府逐瘀汤","生化汤","桃核承气汤"],"a":0,"e":"冲任虚寒，瘀血阻滞。温经汤以吴茱萸、桂枝温经散寒，当归、川芎、芍药养血活血，阿胶、麦冬滋阴，牡丹皮凉血，温经与养血并施。"},{"q":"患者牙痛，齿松牙衄，烦热干渴，舌红苔黄而干。治疗应首选的方剂是","o":["清胃散","泻黄散","黄芩汤","玉女煎","左金丸"],"a":3,"e":"胃热有余，肾水不足。玉女煎以石膏清胃火，熟地滋肾水，知母、麦冬养阴清热，牛膝引热下行，故牙痛齿衄、烦热干渴者宜之。"},{"q":"患者脘腹胀满，不思饮食，口淡无味，舌苔白厚腻，脉濡。治疗应首选的方剂是","o":["藿香正气散","平胃散","四君子汤","参苓白术散","八珍汤"],"a":1,"e":"湿滞脾胃。平胃散以苍术燥湿运脾为君，厚朴行气除满，陈皮理气化湿，甘草、姜、枣调和脾胃，为燥湿健脾之基础方。"},{"q":"患者疔疮初起，发热恶寒，疮形如粟，坚硬如钉，舌红苔黄，脉数。首选治疗方剂是","o":["内补黄芪汤","五味消毒饮","大黄牡丹汤","苇茎汤","阳和汤"],"a":1,"e":"热毒蕴结，疔疮初起。五味消毒饮以金银花、野菊花、蒲公英、紫花地丁、紫背天葵清热解毒、消散疔疮，为治疔疮之要方。"},{"q":"患者身热肢酸，口渴尿赤，咽痛身黄，舌苔黄腻，脉滑数。治疗应首选的方剂是","o":["甘露消毒丹","五苓散","三仁汤","茵陈蒿汤","八正散"],"a":0,"e":"湿热并重，困阻气机。甘露消毒丹清热利湿、化浊解毒，茵陈、滑石、木通利湿于下，黄芩、连翘清热于上，藿香、白蔻仁芳化于中。"},{"q":"患者恶心呕吐，脘腹胀满，常多自利，舌苔白腻而厚，脉缓。本证的病机是","o":["湿重于热，肝脾不和","内伤湿滞，肝胃不和","痰湿内扰，胆胃不和","脾虚湿盛，胃肠不和","湿阻气滞，脾胃不和"],"a":4,"e":"湿浊困阻中焦，脾胃运化失司，气机不畅，故为湿滞脾胃证；治当燥湿运脾、行气和胃，平胃散以苍术、厚朴、陈皮、甘草主之。"},{"q":"患者头痛，胸痛，呃逆日久，内热瞀闷，舌质黯红，有瘀点，脉紧涩。治疗应首选的方剂是","o":["失笑散","血府逐瘀汤","桃核承气汤","复元活血汤","膈下逐瘀汤"],"a":1,"e":"胸中血瘀，气机郁滞。血府逐瘀汤以桃红四物汤活血化瘀，柴胡、枳壳、桔梗疏肝行气，牛膝引血下行，主治胸中血瘀之头痛、胸痛、呃逆日久。"},{"q":"患者平素畏寒肢冷，现便秘腹痛，脐周绞痛，手足不温，苔白不渴，脉沉弦而迟。下列处方最为适合的是","o":["大黄9g，附子12g，细辛3g","大黄10g，芒硝10g，甘遂1g","大黄12g，芒硝12g，炙甘草6g","当归、干姜各5g，附子、人参、甘草各6g，大黄15g，甘草6g","大黄12g，芒硝9g，枳实12g，厚朴24g"],"a":3,"e":"脾阳不足，寒积内停。温脾汤以附子、干姜温阳散寒，大黄、芒硝攻下冷积，人参、当归、甘草益气养血，温通并用，使寒积去而阳气不伤。"},{"q":"患者胸背掣痛不得息，干呕短气，头痛目眩，舌苔白滑，脉沉弦。治疗应首选方剂是","o":["大青龙汤","小青龙汤","十枣汤","半夏白术天麻汤","苓桂术甘汤"],"a":2,"e":"饮停胸胁，气机壅滞。十枣汤以甘遂、大戟、芫花峻逐水饮，大枣十枚顾护脾胃，攻逐之中兼护正气，为治悬饮之主方。"},{"q":"患者呕吐泄泻，胸脘痞闷，舌苔黄腻，脉濡数。治疗应首选的方剂是","o":["八正散","藿香正气散","平胃散","甘露消毒丹","连朴饮"],"a":4,"e":"湿热霍乱，升降失常。连朴饮以黄连清热燥湿，厚朴行气化湿，石菖蒲、半夏和胃止呕，栀子、豆豉清宣郁热，主湿热内蕴、吐泻交作者。"},{"q":"小儿急惊，见身热昏睡，痰盛气粗，发惊发厥，四肢抽搐，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":3,"e":"小儿痰热内闭，肝风内动。抱龙丸以胆南星、天竺黄清热化痰，雄黄解毒，朱砂镇惊安神，麝香开窍，治急惊痰盛气粗、四肢抽搐之证。"},{"q":"患者睾丸肿胀偏坠，坚硬如石，痛引脐腹，阴囊肿大，成痈溃烂，宜用","o":["橘核丸","天台乌药散","吴茱萸汤","暖肝煎","阳和汤"],"a":0,"e":"寒湿结于肾子，气血瘀滞。橘核丸以橘核、川楝子、木香行气散结，桃仁、延胡索活血，海藻、昆布软坚，主治睾丸肿胀坚硬、痛引脐腹之寒湿疝气。"},{"q":"患者尿频尿急，淋沥不畅，溺时涩痛，尿色浑赤，口燥咽干，舌苔黄腻，脉滑数。主治病证是","o":["热淋","膏淋","气淋","血淋","石淋"],"a":0,"e":"湿热下注膀胱，气化不利。八正散以木通、车前子、萹蓄、瞿麦利水通淋，栀子、大黄清热泻火，滑石、甘草梢渗湿缓痛，故主治热淋。"},{"q":"患者咳吐腥臭脓血，胸中隐隐作痛，身有微热，咳嗽痰多，舌红，苔黄腻，脉滑数。首选治疗方剂是","o":["苇茎汤","四妙勇安汤","麻杏石甘汤","定喘汤","泻白散"],"a":0,"e":"热毒壅肺，痰瘀成痈。苇茎汤以苇茎清肺泄热为君，薏苡仁、冬瓜仁排脓消痈，桃仁活血祛瘀，为治肺痈之要方。"},{"q":"患者恶寒发热，头面红肿焮痛，目不能开，咽喉不利，舌燥口渴，舌红苔白兼黄，脉浮数有力。治疗应首选的方剂是","o":["仙方活命饮","黄连解毒汤","普济消毒饮","五味消毒饮","九味羌活汤"],"a":2,"e":"风热疫毒上攻头面。普济消毒饮以酒炒黄芩、黄连清热泻火，牛蒡子、连翘、薄荷、僵蚕疏散风热，升麻、柴胡引药上行，主治大头瘟。"},{"q":"患者胸部闷痛，胸痛彻背，咳唾喘息，短气，舌苔白腻，脉沉弦，宜用","o":["血府逐瘀汤","瓜蒌薤白白酒汤","瓜蒌薤白半夏汤","小陷胸汤","枳实薤白桂枝汤"],"a":1,"e":"胸阳不振，痰浊阻痹。瓜蒌薤白白酒汤以瓜蒌涤痰散结、宽胸利气，薤白通阳散结、行气止痛，白酒行气血以助药力，为治胸痹之基础方。"},{"q":"患者喘咳痰多，短气，胸膈满闷，呼多吸少，腰疼脚软，肢体浮肿，舌苔白滑或白腻，脉弦滑，宜用","o":["小青龙汤","杏苏散","定喘汤","二陈汤","苏子降气汤"],"a":4,"e":"痰涎壅肺，下元虚衰，上实下虚。苏子降气汤以苏子降气平喘，半夏、厚朴、前胡化痰，肉桂温补下元，当归养血润燥，标本兼顾。"},{"q":"患者脘腹胀满，口淡无味，嗳气吞酸，舌苔白滑腻，脉濡。主治病证是","o":["湿滞脾胃证","脾胃气虚证","脾虚湿盛证","内伤湿滞证","湿重于热证"],"a":0,"e":"湿滞脾胃证。湿浊困阻中焦，脾胃运化失司，气机不畅，故见脘腹胀满、口淡无味、苔白滑腻，治当燥湿运脾，平胃散主之。"},{"q":"患者，男，28岁。游泳后感冒，发烧1天，体温39℃，无汗，咳嗽，口渴，舌苔薄黄，脉浮数。可选用下列何方加减治疗","o":["桑菊饮","柴葛解肌汤","升麻葛根汤","麻黄杏仁甘草石膏汤","银翘散"],"a":3,"e":"表邪未解，邪热壅肺。麻黄杏仁甘草石膏汤以麻黄宣肺、石膏清肺，一宣一清，杏仁降气平喘，甘草和中，肺热咳喘而表未尽者宜之。"},{"q":"患者心悸怔忡，虚烦失眠，神疲健忘，或梦遗，手足心热，口舌生疮，大便干结，舌红少苔，脉细数。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","黄连阿胶汤","养心汤"],"a":1,"e":"阴虚血少，心失所养。天王补心丹以生地、天冬、麦冬滋阴清热，当归、丹参补血养心，人参、茯苓益气安神，枣仁、柏子仁养心安神。"},{"q":"患者胸胁疼痛，时发时止，口苦，舌红，苔黄，脉弦数，宜选用","o":["良附丸","血府逐瘀汤","四逆散","越鞠丸","金铃子散"],"a":4,"e":"肝郁化火，气机不畅。金铃子散以川楝子疏肝泄热、行气止痛，延胡索活血行气，两药等分为末，主治肝郁化火之胸胁疼痛、口苦脉弦数。"},{"q":"头痛身热、咳嗽、咽痛、口渴、脉浮数为辨证要点的方剂是","o":["柴葛解肌汤","麻黄杏仁甘草石膏汤","葱豉桔梗汤","升麻葛根汤","银翘散"],"a":2,"e":"风温初起，邪在肺卫。葱豉桔梗汤以葱白、豆豉解表，薄荷、连翘、竹叶清热，桔梗、甘草、山栀宣肺利咽，故以头痛身热、咳嗽咽痛、脉浮数为要点。"},{"q":"患者，女。带下黄臭，阴痒，舌红苔黄腻，脉弦数有力。治疗应首选的方剂是","o":["易黄散","清瘟败毒饮","龙胆泻肝汤","甘露消毒丹","黄连解毒汤"],"a":2,"e":"肝经湿热下注。龙胆泻肝汤以龙胆草、黄芩、栀子清热燥湿，泽泻、木通、车前子利湿下行，当归、生地养血滋阴，柴胡疏肝，使湿热从小便而去。"},{"q":"患者头痛恶寒，身重疼痛，午后身热，苔白不渴，脉濡。治疗应首选的方剂是","o":["防己黄芪汤","三仁汤","羌活胜湿汤","九味羌活汤","藿香正气散"],"a":1,"e":"湿温初起，湿重于热。三仁汤以杏仁宣上、白蔻仁畅中、薏苡仁渗下，滑石、通草、竹叶淡渗利湿，厚朴、半夏行气化湿，气畅则湿自化。"},{"q":"患者咳嗽痰多气急，痰稠色黄，微恶风寒，舌苔黄腻，脉滑数，宜用","o":["苏子降气汤","定喘汤","清气化痰丸","小陷胸汤","小青龙汤"],"a":1,"e":"风寒外束，痰热内蕴。定喘汤以麻黄宣肺平喘，白果敛肺定喘，黄芩、桑白皮清肺热，苏子、杏仁、半夏化痰降气，为治哮喘之常用方。"},{"q":"症见遗精滑泄，神疲乏力，腰痛耳鸣，舌淡苔白，脉细弱者，治宜选用","o":["龙胆泻肝丸","桑螵蛸散","知柏地黄丸","金锁固精丸","缩泉丸"],"a":3,"e":"肾虚精关不固。金锁固精丸以沙苑子补肾固精，芡实、莲须、莲肉涩精止遗，龙骨、牡蛎收涩固精，主治遗精滑泄、腰痛耳鸣之肾虚不固证。"},{"q":"患者发热盗汗，面赤心烦，口干唇燥，大便干结，小便黄赤，舌红苔黄，脉数。治疗应首选的方剂是","o":["黄龙汤","凉膈散","小承气汤","当归六黄汤","甘露消毒丹"],"a":3,"e":"阴虚火旺，迫津外泄。当归六黄汤以当归、生地、熟地养血滋阴，黄连、黄芩、黄柏泻火，倍用黄芪固表止汗，为治阴虚盗汗之要方。"},{"q":"患者肝肾不足，须发早白，齿牙动摇，梦遗滑精，崩漏带下，肾虚不育，腰膝酸软，治宜","o":["七宝美鬓丹","左归丸","右归丸","大补阴丸","肾气丸"],"a":0,"e":"肝肾不足，精血亏虚。七宝美髯丹以何首乌补肝肾、益精血，当归、枸杞、菟丝子、牛膝、补骨脂、茯苓培补肝肾，主治须发早白、齿牙动摇。"},{"q":"胆怯易惊，虚烦不宁，失眠多梦，呕吐呃逆，癫痫等，宜选用","o":["清金化痰丸","二陈汤","贝母瓜蒌散","温胆汤","滚痰丸"],"a":3,"e":"胆胃不和，痰热内扰。温胆汤以半夏、陈皮、茯苓、甘草化痰和胃，竹茹清热化痰止呕，枳实行气消痰，使痰热去而胆胃自安。"},{"q":"患者身重微肿，汗出恶风，小便不利，舌淡苔白，脉浮。本证的病机是","o":["肺脾气虚，风寒外袭","肺脾气虚，风湿外袭","肺脾气虚，风热外袭","肺脾气虚，寒湿外袭","肺脾气虚，湿毒外袭"],"a":1,"e":"表虚不固，风湿外袭。防己黄芪汤证由肺脾气虚、卫表不固，风湿乘虚侵袭，水湿泛溢肌肤所致，故病机为肺脾气虚、风湿外袭。"},{"q":"患者，男，51岁。证见脘腹痞满胀痛，大便秘结，舌苔黄腻，脉沉实。治宜","o":["越鞠丸","葛花解酲汤","木香槟榔丸","枳实导滞丸","健脾丸"],"a":2,"e":"积滞内停，湿蕴生热。木香槟榔丸以木香、槟榔、青皮、陈皮行气导滞，黄连、黄柏清热燥湿，大黄、牵牛子攻积通便，主治脘腹胀痛、便秘或痢疾。"},{"q":"患者，暑病余热未清，气阴两伤而见身热多汗，虚烦少寐，舌红少苔，脉虚数。治疗应首选的方剂是","o":["清暑益气汤","白虎加人参汤","竹叶石膏汤","青蒿鳖甲汤","当归六黄汤"],"a":2,"e":"热病之后，余热未清，气阴两伤。竹叶石膏汤以竹叶、石膏清热除烦，人参、麦冬、粳米、甘草益气养阴，半夏降逆和胃，虚烦少寐者宜之。"},{"q":"患者月经前少腹胀痛，胀甚于痛，舌淡，苔薄白，脉弦紧，宜用","o":["良附丸","天台乌药散","橘核丸","暖肝煎","加味乌药汤"],"a":4,"e":"肝郁气滞，血行不畅。加味乌药汤以乌药、香附、木香、砂仁行气止痛，延胡索活血，甘草缓急，主治经前少腹胀痛、胀甚于痛者。"},{"q":"患者头痛身热，微恶风寒，无汗或有汗不多，咳嗽，心烦，口渴，咽干，舌红，脉数。治疗应首选的方剂是","o":["银翘散","桑菊饮","加减葳蕤汤","葱豉汤","葱白七味饮"],"a":2,"e":"素体阴虚，外感风热。加减葳蕤汤以玉竹滋阴润燥，葱白、豆豉、薄荷、桔梗解表宣肺，白薇清热，为阴虚外感风热之代表方。"},{"q":"患者口干而渴，饮水不解，小便频数，困倦气短，脉虚细无力。治疗宜首选的方剂是","o":["桑杏汤","清燥救肺汤","玉液汤","沙参麦冬汤","增液汤"],"a":2,"e":"气阴两虚，脾肾不足。玉液汤以山药、黄芪益气健脾，知母、天花粉生津止渴，葛根升清，五味子固肾，鸡内金助运，主治消渴之气阴两虚证。"},{"q":"患者胁肋疼痛，嗳气太息，脘腹胀满，脉弦，最宜选用","o":["越鞠丸","一贯煎","小柴胡汤","半夏厚朴汤","柴胡疏肝散"],"a":4,"e":"肝气郁滞，气机不畅。柴胡疏肝散以柴胡疏肝解郁，香附、川芎行气活血，陈皮、枳壳、芍药、甘草理气和营，为治肝郁胁痛之常用方。"},{"q":"患者全身浮肿，身半以下为甚，手足不温，大便溏薄，舌淡胖苔白腻，脉沉迟。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":4,"e":"脾肾阳虚，水气内停。实脾散以附子、干姜温阳，白术、茯苓、甘草健脾，厚朴、木香、草果行气化湿，木瓜化湿和中，温阳与行气利水并施。"},{"q":"以“恶寒发热，无汗头痛，咳痰色白，胸脘满闷，倦怠乏力，苔白，脉弱”为辨证要点的方剂是","o":["小青龙汤","止嗽散","参苏饮","麻黄附子细辛汤","败毒散"],"a":2,"e":"气虚外感风寒，内有痰湿。参苏饮以苏叶、葛根解表散邪，人参益气扶正，二陈汤加枳壳、桔梗理气化痰，故以咳痰色白、倦怠脉弱为要点。"},{"q":"患者恶寒头痛，脘腹闷痛，恶心呕吐，肠鸣泄泻，舌苔白腻，脉浮。主治病证是","o":["外感风热，内伤湿滞证","外感风湿，内有蕴热证","外感风寒，内伤湿滞证","外感风寒，内停水饮证","外感风寒，内有痰饮证"],"a":2,"e":"外感风寒，内伤湿滞。藿香正气散以藿香解表化湿、辟秽和中为君，紫苏、白芷解表散寒，半夏、陈皮、白术、茯苓燥湿健脾，表里同治。"},{"q":"主治心肾不交之健忘失眠，心神不安，或头目眩晕，舌红苔薄白，脉弦细。其方剂为","o":["交泰丸","黄连阿胶汤","甘麦大枣汤","孔圣枕中丹","天王补心丹"],"a":3,"e":"心肾不交，神志不宁。孔圣枕中丹以龟板、龙骨滋阴潜阳、镇惊安神，远志、石菖蒲开窍宁神、交通心肾，主治健忘失眠、心神不安者。"},{"q":"患者，男，42岁。阵发性头晕2年，加重10天。现症见头晕目眩，头重如裹，肢体困重，胸闷呕恶，舌质淡，苔白腻，脉弦滑。治疗宜选用的方剂是","o":["天麻钩藤饮","平胃散","二陈汤","苓桂术甘汤","半夏白术天麻汤"],"a":4,"e":"风痰上扰，蒙蔽清窍。半夏白术天麻汤以半夏、天麻化痰熄风为君，白术、茯苓健脾祛湿，陈皮理气，甘草、姜、枣调和，风痰并治，标本兼顾。"},{"q":"患儿，男，5岁。小儿急惊，热盛抽搐。治疗应首选的方剂是","o":["泻青丸","至宝丹","大定风珠","龙胆泻肝汤","泻黄散"],"a":0,"e":"肝经郁火，热盛动风。泻青丸以龙胆草、栀子、大黄清泻肝火，羌活、防风散风，当归、川芎养血，主治小儿急惊、热盛抽搐之肝火证。"},{"q":"患者全身水肿，尤以身半以下为重，腹胀喘满，二便不利，舌苔白滑，脉沉实。治疗应首选方剂是","o":["实脾散","五皮饮","禹功散","真武汤","十枣汤"],"a":4,"e":"水湿壅盛，泛溢肌肤。十枣汤以甘遂、大戟、芫花攻逐水饮，大枣护胃，水去则肿消，主治水肿腹胀喘满、二便不利之实证。"},{"q":"腹中时痛、喜温欲按、舌淡苔白、脉细弦；或虚劳而心中悸动，虚烦不宁，面色无华，或手足烦热，咽干口燥。方剂宜选用","o":["吴茱萸汤","小建中汤","大建中汤","理中丸","四逆汤"],"a":1,"e":"中焦虚寒，肝脾不和。小建中汤以饴糖为君，合桂枝、芍药辛甘化阳、酸甘化阴，倍芍药缓急止痛，温中补虚，虚劳腹痛喜温喜按者宜之。"},{"q":"以咳嗽，发热不甚，微渴，脉浮数为辨证要点的方剂是","o":["麻黄杏仁甘草石膏汤","桑菊饮","柴葛解肌汤","升麻葛根汤","银翘散"],"a":1,"e":"风温初起，邪在肺卫。桑菊饮以桑叶、菊花疏散风热、宣肺止咳，杏仁、桔梗宣降肺气，连翘、薄荷清热，故以咳嗽、发热不甚、脉浮数为要点。"},{"q":"患者胸脘烦闷，呕吐泄泻，口渴不欲饮，舌苔黄腻，脉濡数。本证的病机是","o":["热毒内蕴，升降失常","湿热内蕴，升降失常","瘀热内蕴，升降失常","寒湿内蕴，升降失常","湿毒内蕴，升降失常"],"a":1,"e":"湿热内蕴，脾胃升降失常。连朴饮证由湿热阻滞中焦，清浊相干，升降失司所致，故见吐泻交作、胸脘烦闷、苔黄腻、脉濡数。"},{"q":"患者三焦火毒热盛证而见有痈疡疔毒，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["普济消毒饮","黄连解毒汤","仙方活命饮","四妙勇安汤","五味消毒饮"],"a":1,"e":"三焦火毒炽盛。黄连解毒汤以黄连泻中焦之火，黄芩泻上焦，黄柏泻下焦，栀子通泻三焦、导热下行，苦寒直折，火毒去则诸症自解。"},{"q":"患者夜热早凉，热退无汗，舌红少苔，脉细数。治疗应首选的方剂是","o":["清营汤","清骨散","青蒿鳖甲汤","秦艽鳖甲散","当归六黄汤"],"a":2,"e":"温病后期，邪伏阴分。青蒿鳖甲汤以青蒿透热外出，鳖甲滋阴搜邪，生地、知母、丹皮养阴凉血，使阴分之邪透出阳分而解。"},{"q":"患者，男，50岁。自述经常便秘。现患者腹痛，脐下绞痛，绕脐不止，手足不温，苔白不渴，脉沉弦而迟。宜选用的方剂是","o":["温脾汤","大陷胸汤","济川煎","调胃承气汤","麻子仁丸"],"a":0,"e":"脾阳不足，寒积内停。温脾汤以附子、干姜温补脾阳，大黄、芒硝攻下冷积，人参、当归、甘草益气养血，温下兼顾，攻补兼施。"},{"q":"患者消渴，消谷善饥。治疗应首选的方剂是","o":["玉女煎","黄芩汤","清胃散","左金丸","泻黄散"],"a":0,"e":"胃热阴虚，虚火上炎。玉女煎以石膏清胃热，熟地滋肾阴，知母、麦冬清热养阴，牛膝引热下行，故消谷善饥、烦热干渴者宜之。"},{"q":"患者呃逆或干呕，虚烦少气，口干，舌红嫩，脉虚数，宜用","o":["旋覆代赭汤","橘皮竹茹汤","丁香柿蒂汤","二陈汤","温胆汤"],"a":1,"e":"胃虚有热，气逆不降。橘皮竹茹汤以橘皮、竹茹理气清热、降逆止呃，人参、甘草、大枣益气补中，生姜和胃，虚热呃逆者宜之。"},{"q":"患者喉间起白如腐不易拭去，咽喉肿痛，鼻干唇燥，呼吸有声，脉细数。治疗宜","o":["清燥救肺汤","养阴清肺汤","百合固金汤","银翘散","琼玉膏"],"a":1,"e":"肺肾阴虚，复感疫毒。养阴清肺汤以生地、玄参、麦冬、白芍养阴润燥，丹皮凉血解毒，贝母化痰，薄荷利咽，为治白喉之主方。"},{"q":"患者下利清水，色纯清，脘腹胀满，腹痛拒按，身热口渴，神倦少气，神昏肢厥，舌苔焦黑，脉虚。治疗应首选方剂是","o":["黄龙汤","大承气汤","调胃承气汤","葛根黄芩黄连汤","安宫牛黄丸"],"a":0,"e":"阳明腑实，气血不足。黄龙汤以大承气汤峻下热结，人参、当归、甘草益气养血，桔梗宣肺通肠，攻补兼施，热结旁流而正虚者宜之。"},{"q":"患者胸膈满闷，脘腹疼痛，恶心呕吐，肠鸣泄泻，恶寒发热，舌苔白腻，脉濡缓。治疗应首选的治法是","o":["解表散寒，理气和胃","解表散寒，和胃止呕","解表散寒，芳化湿浊","解表化湿，通络止痛","解表化湿，理气和中"],"a":4,"e":"外感风寒，内伤湿滞。藿香正气散以藿香解表化湿、芳香辟秽为君，苏叶、白芷发散风寒，半夏、陈皮、厚朴燥湿理气，故能解表化湿、理气和中。"},{"q":"患者阴肿，阴痒，舌红苔黄腻，脉细数有力。治疗应首选的方剂是","o":["消风散","普济消毒饮","龙胆泻肝汤","甘露消毒丹","当归饮子"],"a":2,"e":"肝经湿热下注。龙胆泻肝汤清肝胆实火、利下焦湿热，龙胆草、栀子、黄芩苦寒泻火，泽泻、木通、车前子渗湿，当归、生地养血护阴，标本兼治。"},{"q":"患者汗、吐、下后，里热炽盛而见大热，大汗，大渴，脉洪大者。治疗应首选的方剂是","o":["白虎汤","竹叶石膏汤","白虎加人参汤","白虎加苍术汤","白虎加桂枝汤"],"a":2,"e":"汗吐下后，气津两伤。白虎加人参汤于白虎汤中加人参益气生津，清热与益气养阴并行，故大热、大汗、大渴、脉洪大而虚者宜之。"},{"q":"患儿腰膝酸软，头晕目眩，耳聋耳鸣，盗汗，消渴，骨蒸潮热，手足心热，口燥咽干，囟门不合，舌红少苔，脉沉细数，治疗宜用的方剂是","o":["天王补心丹","炙甘草汤","酸枣仁汤","补中益气汤","六味地黄丸"],"a":4,"e":"肾阴不足，虚火内扰。六味地黄丸以熟地滋肾填精，山茱萸、山药补肝脾，泽泻、丹皮、茯苓泻其虚火湿浊，三补三泻，为滋补肾阴之基础方。"},{"q":"患者高热烦躁，神昏谵语，舌謇肢厥，舌红绛，脉数有利，治疗应首选的方剂是","o":["安宫牛黄丸","犀角地黄汤","至宝丹","清营汤","紫金锭"],"a":0,"e":"热陷心包，痰热蒙蔽。安宫牛黄丸以牛黄清心解毒，犀角、黄连、黄芩、栀子清热凉血，麝香、冰片芳香开窍，主治高热神昏、舌謇肢厥者。"},{"q":"患者头痛微热，小便不利，水肿，舌苔白，脉浮。治疗应首选的治法是","o":["利水渗湿，温阳化饮","利水渗湿，理气健脾","利水渗湿，温中祛寒","利水渗湿，温阳化气","利水渗湿，养阴清热"],"a":3,"e":"膀胱气化不利，水湿内停。五苓散以泽泻、猪苓、茯苓利水渗湿，白术健脾，桂枝温阳化气兼解表邪，故治法为利水渗湿、温阳化气。"},{"q":"证见面色萎黄，饮食不化，四肢乏力，肠鸣泄泻，舌淡苔白腻，脉虚缓，治宜选用何方","o":["补中益气汤","参苓白术散","四君子汤","生脉散","异功散"],"a":1,"e":"脾虚湿盛，运化失司。参苓白术散以四君子汤益气健脾，山药、扁豆、莲子肉健脾渗湿，砂仁醒脾，桔梗载药上行，脾虚湿盛泄泻者宜之。"},{"q":"证见胸脘痞闷，按之则痛，或咳痰黄稠，舌苔黄腻，脉滑数者，治宜选用","o":["小陷胸汤","滚痰丸","二陈汤","贝母瓜蒌散","清金化痰丸"],"a":0,"e":"痰热互结，气郁于胸。小陷胸汤以瓜蒌清热化痰、宽胸散结，黄连泻热，半夏化痰降逆，三药合用，主治胸脘痞闷、按之则痛之痰热结胸。"},{"q":"患儿，女，7岁。咳嗽9天，晨起、晚上阵咳，痰白量多，鼻塞涕稀，纳可，二便正常，舌质淡红，苔白腻，脉滑。治疗宜选的方剂是","o":["苏子降气汤化裁","止嗽散化裁","小青龙汤化裁","苓甘五味姜辛汤化裁","杏苏散化裁"],"a":3,"e":"寒饮停肺，肺失宣降。苓甘五味姜辛汤以干姜温肺散寒化饮，细辛、茯苓温化渗湿，五味子敛肺止咳，甘草调和，为治寒饮咳嗽之基础方。"},{"q":"患者小便不利，头痛微热，烦渴欲饮，甚则水入即吐，舌苔白，脉浮。主治病证是","o":["蓄血证","风水证","阴水证","蓄水证","皮水证"],"a":3,"e":"膀胱气化不利，水蓄下焦。五苓散证由表邪未尽、循经入腑，膀胱气化失司，水蓄不行所致，故为蓄水证，治当利水渗湿、温阳化气。"},{"q":"以恶风，发热，汗出，脉浮缓为辨证要点的方剂是","o":["大青龙汤","败毒散","麻黄汤","小青龙汤","桂枝汤"],"a":4,"e":"外感风寒，营卫不和。桂枝汤以桂枝解肌散邪，芍药敛阴和营，姜、枣、草调和营卫，啜热粥助汗，故以恶风、发热、汗出、脉浮缓为辨证要点。"},{"q":"患者骨蒸潮热，或低热日久不退，形体消瘦，唇红颧赤，舌红少苔，脉细数。治疗应首选的方剂是","o":["凉膈散","清骨散","青蒿鳖甲汤","秦艽鳖甲散","知柏地黄丸"],"a":1,"e":"肝肾阴虚，虚火内灼。清骨散以银柴胡、青蒿、秦艽清透伏热，鳖甲、知母滋阴退蒸，地骨皮、胡黄连清虚火，主治骨蒸潮热、低热日久不退。"},{"q":"患者恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧。治疗应首选的方剂是","o":["桂枝汤","小青龙汤","麻黄汤","大青龙汤","败毒散"],"a":3,"e":"外感风寒，内有郁热。大青龙汤以麻黄、桂枝、生姜发汗解表，石膏清泄里热，杏仁降气，甘草、姜、枣和中，表寒重而里有郁热者宜之。"},{"q":"患者，上中二焦火热证而见睡卧不宁，谵语狂妄，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["白虎汤","凉膈散","黄连解毒汤","清瘟败毒饮","羚角钩藤汤"],"a":1,"e":"上中二焦火热炽盛。凉膈散以连翘、黄芩、栀子、薄荷清上焦郁热，大黄、芒硝、甘草通泻中焦燥实，使热从下而去，为清上泻下之代表方。"},{"q":"患者外感，发汗后病证未解除，仍发热，头眩，身瞤动，振振欲擗地，舌淡胖，苔白滑，脉沉细。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":3,"e":"肾阳虚衰，水湿内停。真武汤以附子温肾助阳，白术、茯苓健脾利水，芍药利小便、柔肝止痛，生姜散水，为温阳利水之要方。"},{"q":"冲任虚寒，瘀血阻滞之漏下证，治宜选方","o":["温经汤","生化汤","桂枝茯苓丸","血府逐瘀汤","补中益气汤"],"a":0,"e":"冲任虚寒，瘀血阻滞。温经汤以吴茱萸、桂枝温经散寒，当归、川芎、芍药养血活血，阿胶、麦冬滋阴养血，参、草益气，寒热虚实兼顾。"},{"q":"患者腰下冷痛，腰重，小便自利，舌淡苔白，脉沉迟。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","肾气丸"],"a":2,"e":"寒湿痹阻腰部。肾著汤以干姜、茯苓温中健脾、利湿，白术燥湿，甘草和中，腰为肾之府，寒湿去则腰重冷痛自除。"},{"q":"患者咳唾胸胁引痛，心下痞硬，干呕短气，头痛目眩，舌苔白滑，脉沉弦。治疗应首选方剂是","o":["小柴胡汤","大柴胡汤","小青龙汤","十枣汤","苓桂术甘汤"],"a":3,"e":"水饮壅盛，结于胸胁。十枣汤以甘遂、大戟、芫花峻下水饮，大枣扶正护胃，主治悬饮咳唾胸胁引痛、心下痞硬、脉沉弦者。"},{"q":"患者身热无汗，头痛身疼，项背拘急，胸满恶食，呕吐腹痛，血气不和，心腹疼痛，月经不调。治疗应首选的方剂是","o":["五积散","麻黄汤","九味羌活汤","藿香正气散","败毒散"],"a":0,"e":"外感风寒，内伤生冷。五积散以麻黄、白芷、葱姜解表散寒，苍术、厚朴、陈皮燥湿健脾，当归、川芎、芍药活血，可散寒、食、气、血、痰五积。"},{"q":"妇人漏下不止，血色黯而有块，淋漓不畅，舌质黯红，脉细而涩。治疗应首选的方剂是","o":["复元活血汤","桂枝茯苓丸","失笑散","生化汤","温经汤"],"a":4,"e":"冲任虚寒，瘀阻胞宫。温经汤温经散寒、养血祛瘀，使寒散瘀行、血得归经，故漏下不止、血色黯有块、脉细涩者宜之。"},{"q":"患者五更泄泻，不思饮食，食不消化，舌淡，苔薄白，脉沉迟无力。治疗首先的方剂是","o":["四神丸","理中丸","真人养脏汤","桃花汤","补中益气汤"],"a":0,"e":"脾肾阳虚，肠失温固。四神丸以补骨脂温补命门，肉豆蔻、吴茱萸温中涩肠，五味子收敛，姜、枣同煎，主治五更泄泻、食少不化。"},{"q":"患者身热谵语，斑色紫黑，舌深绛起刺，脉数。治疗应首选的方剂是","o":["清营汤","犀角地黄汤","清暑益气汤","青蒿鳖甲汤","黄连解毒汤"],"a":1,"e":"热入血分，耗血动血。犀角地黄汤以犀角凉血解毒，生地养阴清热，赤芍、丹皮凉血散血，使热清血宁而无耗血动血之虞。"},{"q":"患者出现产后恶露不行，小腹冷痛，拒按，脉细涩，舌质黯淡。治疗应首选的方剂是","o":["生化汤","温经汤","十灰散","少腹逐瘀汤","温脾汤"],"a":0,"e":"产后血虚寒凝，瘀阻胞宫。生化汤以当归养血活血，川芎、桃仁活血祛瘀，炮姜温经止痛，甘草调和，寓生新于化瘀之中，为产后常用方。"},{"q":"患者腹痛时作时止，往来上下，或呕吐清水涎沫，或吐蛔虫，多食而瘦，面色青黄。治疗应首选的方剂是","o":["乌梅丸","化虫丸","吴茱萸汤","健脾丸","枳实导滞丸"],"a":1,"e":"肠中虫积，气机壅滞。化虫丸以鹤虱、苦楝根皮、槟榔、使君子杀虫，配大黄、牵牛子泻下排虫，主治腹痛时作、吐蛔、面黄肌瘦之虫积。"},{"q":"患者往来寒热，胸胁苦满，呕不止，郁郁微烦，心下痞硬，协热下利，舌苔黄，脉弦数有力。治疗应首选的方剂是","o":["大承气汤","小柴胡汤","败毒散","大柴胡汤","防风通圣散"],"a":3,"e":"少阳阳明合病。大柴胡汤以小柴胡汤去人参、甘草，加大黄、枳实、芍药，和解少阳兼通泻阳明，少阳未解而里实已成者宜之。"},{"q":"患者便秘5天。现仍大便不通，频转矢气，脘腹痞满，腹痛拒按。医生开出大承气汤，嘱咐患者使用注意不正确的是","o":["临卧服","中病即止","勿食油腻及不易消化的食物","大黄后下","芒硝溶服"],"a":0,"e":"大承气汤宜先煎枳实、厚朴，后下大黄，芒硝溶服，中病即止，忌食油腻难化之物；临卧服非其服法，故为不正确之嘱。"},{"q":"咳血方中用以清肝泻火的药物是","o":["青黛","龙胆草","黄芩","大黄","柴胡"],"a":0,"e":"咳血方以青黛清肝泻火、凉血止血，配栀子清心除烦，瓜蒌仁、海浮石清热化痰，诃子敛肺止咳，主治肝火犯肺之咳血。"},{"q":"暴哑为大寒直犯肺肾，上窒窍隧，下闭肾气所致者，治疗首选的方剂是","o":["回阳救急汤","肾气丸","右归丸","参附汤","麻黄附子细辛汤"],"a":4,"e":"阳虚外感，寒邪直中少阴。麻黄附子细辛汤以麻黄解表散寒，附子温肾助阳，细辛通彻表里，助阳解表，暴哑属大寒犯肺肾者宜之。"},{"q":"患者面目俱黄，黄色鲜明，发热无汗，口渴欲饮，小便短赤，大便不爽，舌红苔黄腻，脉滑数有力。本证的病机是","o":["湿热阻滞，熏蒸肝胆","湿热瘀滞，熏蒸肝胆","湿热瘀滞，熏蒸胆胃","湿热痰滞，熏蒸肝胆","湿热阻滞，熏蒸脾胃"],"a":1,"e":"湿热内蕴，熏蒸肝胆，胆汁外溢肌肤。茵陈蒿汤以茵陈清热利湿退黄，栀子清利三焦，大黄泻热逐瘀，使湿热瘀滞从二便分消。"},{"q":"患者大便干结，小便频数，脘腹胀痛，舌红苔黄，脉数。治疗应首选的方剂是","o":["大承气汤","小承气汤","麻子仁丸","济川煎","黄龙汤"],"a":2,"e":"肠胃燥热，脾约津亏。麻子仁丸以小承气汤泄热通便，麻子仁、杏仁、芍药、蜂蜜润肠滋燥，为润肠泄热、行气通便之常用方。"},{"q":"患者心下至少腹硬满疼痛而痛不可近，大便秘结，短期烦躁，舌燥而渴，脉沉紧，按之有力。本病的病机是","o":["水热互结于心下","痰热互结与心下","瘀热互结与心下","水湿结聚与心下","寒积心下"],"a":0,"e":"水热互结于胸脘。大陷胸汤以甘遂峻逐水饮，大黄、芒硝泻热破结，水热并从下夺，故心下至少腹硬满、痛不可近者属之。"},{"q":"患者大便秘结，小便清长，腰膝酸冷，舌淡苔白，脉沉迟。治疗应首选方剂是","o":["济川煎","肾气丸","五仁丸","温脾汤","脾约丸"],"a":0,"e":"肾虚精亏，肠道失润。济川煎以肉苁蓉温肾益精、润肠通便，当归养血，牛膝补肾下行，枳壳、泽泻、升麻升降相因，寓通于补。"},{"q":"时值深秋，患者头微痛，恶寒无汗，咳嗽痰稀，鼻塞咽干已两日，苔白，脉弦。宜首选的方剂是","o":["桑杏汤","麻黄汤","杏苏散","清燥救肺汤","桑菊饮"],"a":2,"e":"外感凉燥，肺失宣降。杏苏散以苏叶、生姜解表散寒，杏仁、前胡、桔梗宣降肺气，半夏、陈皮、茯苓化痰，枳壳、甘草调气，为治凉燥之代表方。"},{"q":"升麻葛根汤的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热，喘咳，苔黄，脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":4,"e":"麻疹初起，疹毒不透。升麻葛根汤以升麻、葛根解肌透疹，芍药、甘草和营解毒，故以疹发不出或出而不畅、舌红脉数为辨证要点。"},{"q":"患者，男，22岁。心下至少腹硬满疼痛而痛不可近，大便秘结，日晡潮热，舌燥而渴，脉沉紧，按之有力。医生开出的方剂是大陷胸汤，方中君药是","o":["大黄","芒硝","甘遂","大戟","芫花"],"a":2,"e":"大陷胸汤以甘遂为君，峻逐水饮、泻热破结，大黄、芒硝为臣佐，泻热荡实、软坚散结，三药合用，使水热之结从大便而去。"},{"q":"症见大便下血，先便后血，血色黯淡，伴有四肢不温，面色萎黄，舌淡苔白，脉沉细无力，治宜选用","o":["槐花散","黄土汤","芍药汤","归脾汤","理中丸"],"a":1,"e":"脾阳不足，统摄无权。黄土汤以灶心黄土温中止血为君，白术、附子温阳健脾，生地、阿胶养血止血，黄芩制温燥，甘草调和，标本兼顾。"},{"q":"患者痈疽溃后，脓水稀少，腐肉不去，新肉不生，神倦，面色少华，脉虚无力。首选治疗方剂是","o":["补中益气汤","托里消毒散","四妙勇安汤","仙方活命饮","阳和汤"],"a":1,"e":"气血两虚，余毒未尽。托里消毒散以人参、黄芪、白术、茯苓补气，当归、芍药、川芎养血，金银花、白芷、皂角刺解毒排脓，扶正托毒并施。"},{"q":"患者，男，68岁。平素易感冒，此次因气温突降而感冒2天，腹泻1天，症见“恶寒发热，头痛，肢体酸痛，无汗，鼻塞，泄泻伴腹痛，舌淡苔白，脉浮而按之无力”。治疗首选的方剂是","o":["九味羌活汤","参苏饮","麻黄汤","败毒散","葱白七味饮"],"a":3,"e":"气虚外感风寒湿。败毒散以羌活、独活、川芎、柴胡解表散寒、祛湿止痛，人参益气扶正，桔梗、枳壳、前胡、茯苓理气化痰，气虚感冒者宜之。"},{"q":"患者遗精淋浊，血崩带下，遇劳则发。治疗应首选的方剂是","o":["导赤散","八正散","完带汤","归脾汤","清心莲子饮"],"a":4,"e":"心火偏旺，气阴两虚，湿热下注。清心莲子饮以石莲子清心火，黄芩、地骨皮清热，人参、黄芪、麦冬益气养阴，车前子、茯苓利湿，遇劳即发者宜之。"},{"q":"患者发热咳嗽，口渴欲饮，心烦不寐，小便不利，舌红苔微黄，脉细数。主治病证是","o":["水热互结伤阴证","瘀热互结伤阴证","湿热互结伤阴证","痰瘀互结伤阴证","痰热互结伤阴证"],"a":0,"e":"水热互结，邪热伤阴。猪苓汤以猪苓、茯苓、泽泻利水渗湿，滑石清热利水，阿胶滋阴润燥，利水而不伤阴，为治水热互结伤阴证之要方。"},{"q":"麻黄汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":2,"e":"外感风寒表实证。麻黄汤以麻黄发汗解表、宣肺平喘，桂枝助汗，杏仁降气，甘草和中，故以恶寒发热、无汗而喘、脉浮紧为辨证要点。"},{"q":"患者带下量多，清稀色白，无异味，大便溏薄，舌淡苔白，脉缓。治疗应首选的方剂是","o":["完带汤","清带汤","二妙散","易黄汤","固冲汤"],"a":0,"e":"脾虚肝郁，湿浊下注。完带汤以白术、山药健脾除湿，人参、甘草补气，苍术、陈皮燥湿运脾，柴胡、白芍疏肝，车前子利湿，带下清稀无臭者宜之。"},{"q":"主治为阴血亏虚、心肾失调之精神恍惚，惊悸怔忡，夜寐多梦，健忘盗汗，舌红少苔，脉细而数的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","柏子养心丸","养心汤"],"a":3,"e":"阴血亏虚，心肾失调。柏子养心丸以柏子仁养心安神，人参、黄芪、茯苓益气，当归、川芎、熟地养血，枸杞子、麦冬滋阴，主治惊悸怔忡、健忘盗汗。"},{"q":"患者微恶风寒，头痛无汗，鼻塞流涕，喷嚏频作，舌苔薄白，脉浮。治宜选用","o":["桑菊饮","桑杏汤","杏苏散","清燥救肺汤","葱豉汤"],"a":4,"e":"外感风寒轻证。葱豉汤以葱白辛温通阳、豆豉解表宣郁，药性平和，主治恶寒微热、头痛鼻塞、喷嚏、脉浮之风寒轻证。"},{"q":"患者身重疼痛，胸闷不饥，午后身热，面色淡黄，舌淡苔白，脉弦细而濡。治疗应首选的治法是","o":["宣畅气机，清热解毒","宣畅气机，淡渗利湿","宣畅气机，芳化湿浊","宣畅气机，清利湿热","宣畅气机，清化瘀热"],"a":3,"e":"湿温初起，湿遏热伏。三仁汤以杏仁宣上、白蔻仁畅中、薏苡仁渗下，配滑石、通草、竹叶清热利湿，厚朴、半夏行气化湿，故能宣畅气机、清利湿热。"},{"q":"患者头痛身热，干咳无痰，气逆而喘，咽喉干燥，鼻燥，胸满胁痛，心烦口渴，舌干少苔，脉虚大而数。治疗宜首选的方剂是","o":["桑菊饮","玉液汤","银翘散","清燥救肺汤","养阴清肺汤"],"a":3,"e":"温燥伤肺，气阴两伤。清燥救肺汤以桑叶清宣燥热，石膏、麦冬清肺养阴，阿胶、胡麻仁润燥，人参、甘草益气，杏仁、枇杷叶降气，为治温燥之要方。"},{"q":"患者，热入血分而见吐血、衄血，舌深绛起刺，脉数。治疗应首选的方剂是","o":["十灰散","犀角地黄汤","黄连解毒汤","清瘟败毒饮","小蓟饮子"],"a":1,"e":"热入血分，动血耗血。犀角地黄汤以犀角凉血解毒，生地清热养阴，赤芍、丹皮凉血散血，主治热入血分之吐血、衄血、斑色紫黑、舌深绛。"},{"q":"患者，女，53岁，暑月前来就诊，症见身热烦渴，小便不利，或泄泻。此病证的治法是","o":["解表清里","化湿和中","清暑利湿","清肺平喘","疏风清热"],"a":2,"e":"暑湿内阻。六一散以滑石六份、甘草一份，清暑利湿，使暑湿从小便而去，故身热烦渴、小便不利者治法为清暑利湿。"},{"q":"患者疮痈内已成脓，无力外溃，漫肿无头，痠胀热痛。首选治疗方剂是","o":["苇茎汤","消瘰丸","黄连解毒汤","透脓散","大黄牡丹汤"],"a":3,"e":"正虚毒盛，不能托毒外透。透脓散以黄芪益气托毒，当归、川芎养血活血，穿山甲、皂角刺溃坚透脓，主治疮痈成脓而无力外溃者。"},{"q":"患者大热渴饮，头痛如劈，干呕狂躁，谵语神昏，舌绛唇焦，脉沉细数。治疗应首选的方剂是","o":["白虎汤","竹叶石膏汤","普济消毒饮","黄连解毒汤","清瘟败毒饮"],"a":4,"e":"热毒充斥，气血两燔。清瘟败毒饮以石膏、知母清阳明之热，犀角、生地、玄参凉血解毒，黄连、黄芩、栀子泻火，气血两清，为治疫疹之主力。"},{"q":"患者，女，6岁。病后持续性咳嗽，咯痰，清晨或夜间咳嗽严重，伴有气喘，脘痞，食少难消，舌苔白腻，脉滑。治疗宜选的方剂是","o":["泻白散","苏子降气汤","小青龙汤","三子养亲汤","定喘汤"],"a":3,"e":"痰壅气逆，肺失肃降。三子养亲汤以白芥子畅膈化痰，苏子降气行痰，莱菔子消食导滞，三药各有所长，主治痰多胸痞、食少难消之喘咳。"},{"q":"患者，女，20岁。感冒1天。症见恶寒发热，头痛无汗，胸脘痞闷，不欲饮食，并伴恶心，舌苔薄白，脉浮。可用下列何方加味治疗","o":["香苏散","葱豉桔梗汤","败毒散","九味羌活汤","小青龙汤"],"a":0,"e":"外感风寒，内有气滞。香苏散以紫苏叶解表散寒、理气宽中，香附、陈皮行气解郁，甘草调和，为治四时感冒兼气滞之轻剂。"},{"q":"患者小便频数、浑浊不清，白如米泔，舌淡苔白，脉沉。治疗应首选的方剂是","o":["导赤散","小蓟饮子","萆薢分清饮","八正散","猪苓汤"],"a":2,"e":"下焦虚寒，湿浊下注。萆薢分清饮以萆薢利湿化浊，益智仁、乌药温肾缩尿，石菖蒲化浊通窍，主治膏淋白浊、小便频数浑浊如米泔。"},{"q":"患者肩背痛不可回顾，头痛身重，舌淡苔白，脉浮。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":1,"e":"风湿在表，经络不畅。羌活胜湿汤以羌活、独活祛风除湿，防风、藁本、蔓荆子散邪止痛，川芎活血行气，甘草调和，湿邪在表者宜之。"},{"q":"患者，男，61岁。10天前因劳累后出现头痛，头部昏蒙，隐隐作痛，偶有胸闷，乏力，纳差，二便调，舌淡苔白腻，脉弦滑。治疗应首选的方剂是","o":["半夏白术天麻汤加竹茹、黄连","半夏白术天麻汤加黄芪、川芎","川芎茶调散加苍术、厚朴","九味羌活汤加陈皮、茯苓","二陈汤加川芎"],"a":1,"e":"风痰上扰，兼气虚血滞。半夏白术天麻汤化痰熄风，加黄芪益气升清、川芎行气活血，标本兼顾，故头痛昏蒙、乏力纳差、脉弦滑者宜之。"},{"q":"患者瘀阻头面，头痛昏晕，耳聋，脱发，面色青紫，治宜选用","o":["血府逐瘀汤","通窍活血汤","少腹逐瘀汤","身痛逐瘀汤","复元活血汤"],"a":1,"e":"瘀血阻滞头面，清窍不通。通窍活血汤以麝香、老葱通窍开闭，桃仁、红花、赤芍、川芎活血化瘀，黄酒煎服助药上行，主治头痛昏晕、脱发。"},{"q":"患者有风湿性关节炎病史，近期腰膝疼痛，双下肢晨起麻木不仁，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"痹证日久，肝肾两虚，气血不足。独活寄生汤以独活、细辛、防风祛风湿，桑寄生、杜仲、牛膝补肝肾，人参、当归、芍药益气养血，扶正祛邪。"},{"q":"患者，女，32岁，胆怯易惊，虚烦不宁，失眠多梦，呕吐呃逆，舌苔白腻微黄，脉弦滑略数。选用何方为佳","o":["清气化痰丸","温胆汤","贝母瓜蒌散","二陈汤","茯苓丸"],"a":1,"e":"胆胃不和，痰热内扰。温胆汤以二陈汤化痰和胃，竹茹清热止呕，枳实行气消痰，痰热去则胆自宁，故胆怯易惊、虚烦失眠者宜之。"},{"q":"患者，女，64岁。证见脘腹胀痛，下痢泄泻，小便短赤，舌苔黄腻，脉沉有力。治宜","o":["芍药汤","枳实导滞丸","保和丸","木香槟榔丸","健脾丸"],"a":1,"e":"湿热食积，内阻肠胃。枳实导滞丸以大黄攻积泻热，枳实、神曲消食导滞，黄芩、黄连清热燥湿，茯苓、泽泻、白术利湿健脾，通因通用。"},{"q":"患者昨日外出后汗出当风，出现肩臂疼痛，难以转侧，舌淡苔白，脉浮。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":1,"e":"风湿在表，卫气不畅。羌活胜湿汤以羌活、独活为君，祛一身风湿，防风、藁本、蔓荆子散风止痛，川芎、甘草行气缓急，汗出当风者宜之。"},{"q":"患者，男，55岁。腹痛便秘，脐下绞痛，绕脐不止，手足不温，苔白不渴，脉沉弦而迟。医生选用温脾汤治疗，该方组成药物是","o":["附子、细辛、干姜、大黄、人参","附子、大黄、芒硝、人参、当归","干姜、大黄、枳实、厚朴、人参","干姜、大黄、芒硝、附子、芍药","附子、干姜、细辛、人参、芒硝"],"a":1,"e":"温脾汤以附子、干姜温阳散寒，大黄、芒硝攻下冷积，人参、当归、甘草益气养血，属温下之剂，故组方当取附子、大黄、芒硝、人参、当归。"},{"q":"患者见手足不温，胁肋胀痛，脘腹疼痛，泄利下重，脉弦。首选方剂是","o":["四逆散","小柴胡汤","茵陈蒿汤","龙胆泻肝汤","蒿芩清胆汤"],"a":0,"e":"阳郁厥逆，肝脾不和。四逆散以柴胡疏肝解郁，枳实破气散结，芍药、甘草柔肝缓急，使气机宣通、阳气外达，故手足不温而脉弦者宜之。"},{"q":"患者，女，44岁。头痛以巅顶为主，痛甚时烦躁欲死，伴有恶心呕吐，畏寒喜热，手足不温，口不渴，舌淡苔白，脉沉弦迟。宜选择下列哪方治疗","o":["吴茱萸汤","小建中汤","当归四逆汤","四逆汤","大建中汤"],"a":0,"e":"肝胃虚寒，浊阴上逆。吴茱萸汤以吴茱萸温胃暖肝、降逆止呕为君，人参、大枣益气健脾，生姜温胃散寒，巅顶头痛、干呕吐涎沫者宜之。"},{"q":"患者症见身热汗多，口渴心烦，小便短赤，体倦少气，精神不振，脉虚数。治疗应首选","o":["清暑益气汤","竹叶石膏汤","香薷散","桂苓甘露散","六一散"],"a":0,"e":"暑热伤气，气津两伤。清暑益气汤以西洋参、石斛、麦冬益气养阴，黄连、竹叶、荷梗清暑泻热，知母、西瓜翠衣清热生津，体倦少气、脉虚数者宜之。"},{"q":"患者胸膈痞闷，脘腹胀痛，嗳腐吞酸，恶心呕吐，饮食不消，治宜选用","o":["半夏泻心汤","柴胡疏肝散","越鞠丸","枳实消痞丸","半夏厚朴汤"],"a":2,"e":"气血痰火湿食诸郁为病。越鞠丸以香附行气解郁为君，川芎活血，栀子清热，苍术燥湿，神曲消食，五味同治六郁，示人以治郁大法。"},{"q":"患者牙宣出血，牙龈红肿溃烂，口气热臭，口干舌燥，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["清胃散","左金丸","凉膈散","清瘟败毒饮","普济消毒饮"],"a":0,"e":"胃火炽盛，循经上攻。清胃散以黄连清胃泻火，升麻清热解毒、引药上行，生地、丹皮凉血养阴，当归养血和血，为治胃火牙痛之要方。"},{"q":"患者骨蒸潮热，盗汗遗精，咳嗽咳血，心烦易怒，足膝疼热，舌红少苔，尺脉数而有力，治疗宜用的方剂是","o":["左归丸","肾气丸","大补阴丸","小柴胡汤","一贯煎"],"a":2,"e":"肝肾阴虚，虚火亢盛。大补阴丸以熟地、龟板滋阴潜阳，黄柏、知母苦寒泻火，猪脊髓、蜂蜜补髓润燥，培本清源，壮水以制火。"},{"q":"九味羌活汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":3,"e":"外感风寒湿邪，内有蕴热。九味羌活汤以羌活为君，配防风、苍术、细辛、白芷、川芎、生地、黄芩、甘草，发汗祛湿兼清里热，故口苦微渴。"},{"q":"患者腹痛便秘，胁下偏痛，发热，畏寒肢冷，舌苔白腻，脉弦紧。宜选用的方剂是","o":["温脾汤","大陷胸汤","归脾汤","大黄牡丹汤","大黄附子汤"],"a":4,"e":"寒积里实，阳气被遏。大黄附子汤以附子、细辛温散寒凝，大黄泻下通便，寒热并用，使冷积去而阳气复，胁下偏痛、脉弦紧者宜之。"},{"q":"患者下利清水，色纯青，其气臭秽，脐腹疼痛，按之坚硬有块，口舌干燥，脉滑实。最宜选用的方剂是","o":["温脾汤","十枣汤","济川煎","麻子仁丸","大承气汤"],"a":4,"e":"阳明腑实，热结旁流。燥屎内结，肠中津液从旁而下，故下利清水而臭秽；大承气汤峻下热结，通因通用，燥屎去则下利自止。"},{"q":"患者大便不通，频转矢气，脘腹痞满，腹痛拒按，按之硬，潮热谵语，手足濈然汗出，舌苔黄燥起刺，脉沉实。最宜选用的方剂是","o":["济川煎","大承气汤","大柴胡汤","桃核承气汤","增液承气汤"],"a":1,"e":"阳明腑实证。燥屎内结，腑气不通，故痞满燥实坚俱见；大承气汤以大黄泻热通便，芒硝软坚润燥，枳实、厚朴行气除满，急下存阴。"},{"q":"以恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴为辨证要点的方剂是","o":["大青龙汤","麻黄杏仁甘草石膏汤","九味羌活汤","白虎汤","败毒散"],"a":2,"e":"外感风寒湿，内有蕴热。九味羌活汤发汗祛湿、兼清里热，羌活、防风、苍术、细辛、白芷散寒除湿，生地、黄芩清泄里热，故以口苦微渴为要点。"},{"q":"患者受刀伤后，筋断骨折，瘀血肿痛。治疗应首选的方剂是","o":["七厘散","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":0,"e":"跌打损伤，筋断骨折，瘀血肿痛。七厘散以血竭、乳香、没药活血散瘀、消肿止痛，红花、儿茶、朱砂、冰片、麝香通窍定痛，内服外敷皆可。"},{"q":"患者因秽恶痰浊郁阻，感脘腹胀闷疼痛，恶心呕吐，泄泻，舌苔厚腻，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":4,"e":"秽恶痰浊郁阻中焦。紫金锭以山慈菇、红大戟、千金子霜、麝香、雄黄辟秽解毒、化痰开窍、消肿止痛，主治脘腹胀闷、吐泻之痧胀。"},{"q":"患者心下坚，大如盘，边如旋盘，宜用","o":["枳术汤","枳术丸","枳实消痞丸","半夏泻心汤","香砂六君子汤"],"a":0,"e":"证属水饮停聚心下、气机壅滞，枳术汤以枳实行气消痞、白术健脾化饮，消补兼施，为“心下坚大如盘”之主方。"},{"q":"患者温病后期，神倦瘈疭，舌绛苔少，脉气虚弱，有时时欲脱之势。治疗首选的方剂是","o":["清营汤","羚角钩藤汤","大定风珠","天麻钩藤饮","青蒿鳖甲汤"],"a":2,"e":"证属温病后期真阴耗损、虚风内动，大定风珠滋阴息风、潜阳固脱，为阴虚风动重证之主方。"},{"q":"患者小便频数，遗尿，小腹怕冷，舌淡，脉沉弱，治适宜选","o":["天台乌药散","缩泉丸","暖肝煎","金锁固精丸","桑螵蛸散"],"a":1,"e":"证属肾气不足、膀胱虚寒失约，缩泉丸温肾祛寒、缩尿止遗；桑螵蛸散长于调补心肾，兼心神恍惚者宜之。"},{"q":"患者胸脘痞满，不思饮食，舌淡苔白，脉弱，宜用","o":["枳术汤","枳术丸","枳实消痞丸","半夏泻心汤","香砂六君子汤"],"a":1,"e":"证属脾虚气滞、饮食停积，枳术丸健脾行气、消补兼施，白术用量重于枳实，故脾虚痞满者宜之。"},{"q":"以疹发不出或出而不畅，舌红，脉数为辨证要点的方剂是","o":["桑菊饮","麻黄杏仁甘草石膏汤","柴葛解肌汤","银翘散","升麻葛根汤"],"a":4,"e":"证属麻疹初起、疹毒透发不畅，升麻葛根汤解肌透疹、清热解毒，以疹出不畅、舌红脉数为要点。"},{"q":"患者头微痛，恶寒无汗，咳嗽痰稀，鼻塞嗌干，苔白脉浮。治当首选的方剂是","o":["桂枝汤","三拗汤","加味香苏散","葱白七味饮","杏苏散"],"a":4,"e":"证属外感凉燥、肺失宣降，杏苏散轻宣凉燥、理肺化痰，燥邪犯肺而痰稀鼻塞者宜之。"},{"q":"患者，外科疮疡，心胸烦闷，大便干结等。治疗应首选的方剂是","o":["泻心汤","黄芩汤","五味消毒饮","仙方活命饮","普济消毒饮"],"a":0,"e":"证属邪火内炽、三焦积热，泻心汤苦寒直折，泻火解毒、燥湿泄热，火毒疮疡兼便结者宜之。"},{"q":"症见久咳不已，咳甚则气喘自汗，痰少而黏，脉虚数。治宜首选","o":["麻黄汤","生脉散","小青龙汤","九仙散","泻白散"],"a":3,"e":"证属久咳肺虚、气阴两伤，九仙散敛肺止咳、益气养阴，为久咳不已、脉虚数者之主方。"},{"q":"患者高热烦躁，神昏谵语，痉厥，口渴唇焦，舌红绛，脉数实，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":1,"e":"证属热闭心包、肝风内动，紫雪清热开窍、息风止痉，长于止痉，痉厥为主者首选。"},{"q":"以“恶寒发热，头身重痛，无汗，脉浮、重按无力”为辨证要点的方是","o":["九味羌活汤","败毒散","再造散","参苏饮","葱白七味饮"],"a":1,"e":"证属正气不足、外感风寒湿邪，败毒散散寒祛湿、益气解表，脉浮而重按无力为其要点。"},{"q":"患者微恶风发热，咳嗽咽痒，咯痰不爽，舌苔薄白，脉浮缓。治疗应首选的方剂是","o":["败毒散","止嗽散","葱豉桔梗汤","香苏散","九味羌活汤"],"a":1,"e":"证属风邪犯肺、肺气不宣，止嗽散宣利肺气、疏风止咳，咳嗽咽痒、咯痰不爽者宜之。"},{"q":"患者胸闷腹胀，身热口渴，肢酸倦怠，咽痛颐肿，身目发黄，小便短赤，舌苔干黄，脉滑数。主治病证是","o":["暑温时疫之湿重于热证","暑温时疫之湿热并重证","湿温时疫之湿热并重证","湿温时疫之湿重于热证","湿温时疫之热重于湿证"],"a":2,"e":"证属湿温时疫、湿热并重，甘露消毒丹利湿化浊、清热解毒，以咽痛颐肿、身目发黄、苔干黄为要点。"},{"q":"小柴胡汤证误用攻下，损伤中阳，少阳邪热乘虚内陷致寒热互结，症见心下痞满不痛，呕吐泻利，苔腻微黄，治疗应选的方剂是","o":["半夏泻心汤","小柴胡汤","大柴胡汤","生姜泻心汤","黄连汤"],"a":0,"e":"证属少阳误下、中阳受损、寒热互结心下，半夏泻心汤寒热平调、散结除痞，痞满而不痛者宜之。"},{"q":"患者腰膝疼痛，肢节屈伸不利，畏寒喜暖，心悸气短，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"证属痹证日久、肝肾两虚、气血不足，独活寄生汤祛风湿、止痹痛、益肝肾、补气血。"},{"q":"患者大热烦躁，口燥咽干，错语不眠，小便黄赤，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["泻心汤","大承气汤","清瘟败毒饮","普济消毒饮","黄连解毒汤"],"a":4,"e":"证属三焦火毒热盛，黄连解毒汤泻火解毒，大热烦躁、错语不眠、脉数有力者宜之。"},{"q":"患者脾热弄舌，舌红，脉数。治疗应首选的方剂是","o":["泻黄散","玉女煎","清胃散","左金丸","黄土汤"],"a":0,"e":"证属脾胃伏火，泻黄散清泻脾胃伏火兼以疏散，为脾热弄舌之主方。"},{"q":"患者，女，46岁。证见脘腹胀痛，大便秘结，小便短赤，舌苔黄腻，脉沉有力。治宜","o":["木香槟榔丸","葛花解醒汤","保和丸","枳实导滞丸","健脾丸"],"a":3,"e":"证属湿热食积内阻、气机壅滞，枳实导滞丸消导化积、清热祛湿，下痢或便秘均可选用。"},{"q":"患者恶寒渐轻，身热增盛，无汗头痛，目疼鼻干，心烦不眠，咽干耳聋，眼眶痛，舌苔薄黄，脉浮微洪。治疗宜首选的方剂是","o":["升麻葛根汤","桑菊饮","柴葛解肌汤","麻黄杏仁甘草石膏汤","银翘散"],"a":2,"e":"证属太阳阳明合病、表邪入里化热，柴葛解肌汤解肌清热，以眼眶痛、鼻干、脉浮微洪为要点。"},{"q":"某女性患者，妊娠过程中出现下血，其血色紫黯，腹痛拒按，胎动不安。治疗应首选的方剂是","o":["桂枝茯苓丸","四逆散","生化汤","温经汤","逍遥丸"],"a":0,"e":"证属瘀血癥块阻滞胞宫，桂枝茯苓丸活血化瘀、缓消癥块，妊娠漏下而腹痛拒按者宜之。"},{"q":"患者四肢浮肿，恶寒身热，无汗，烦躁，脉浮紧。治疗应首选的方剂是","o":["大青龙汤","桂枝汤","麻黄汤","小青龙汤","败毒散"],"a":0,"e":"证属外感风寒、内有郁热之溢饮，大青龙汤发汗解表、清热除烦，水肿兼烦躁、脉浮紧者宜之。"},{"q":"患者筋脉拘急，手足瘈疭，或头晕目眩，舌绛苔少，脉细数。治疗首选的方剂是","o":["天麻钩藤饮","羚角钩藤汤","阿胶鸡子黄汤","大定风珠","青蒿鳖甲汤"],"a":2,"e":"证属热伤阴血、血虚生风，阿胶鸡子黄汤滋阴养血、柔肝息风，与阴虚风动之大定风珠有别。"},{"q":"患者，女，58岁。左侧肢体一过性麻木无力伴头晕1周。发作时左侧肢体麻木无力，持物不能，站立不稳，言语略含糊，伴头晕，持续约30分钟症状好转，纳差，二便正常，舌黯苔白腻，脉弦滑。治疗应首选的方剂是","o":["小活络丹","定痫丸","半夏白术天麻汤加减","天麻钩藤饮加减","镇肝熄风汤加减"],"a":2,"e":"证属风痰上扰、痰浊阻络，半夏白术天麻汤化痰息风、健脾祛湿，眩晕而苔白腻、脉弦滑者宜之。"},{"q":"患者，女，25岁，正值盛暑前来就诊，见身热烦渴，泄泻。治宜首选","o":["清暑益气汤","白虎汤","生脉散","泻白散","六一散"],"a":4,"e":"证属暑湿伤中、湿热内蕴，六一散清暑利湿，药仅滑石、甘草，为暑湿轻证之基础方。"},{"q":"患者呕吐，呃逆，口渴咽干，舌红少苔，脉虚数。治疗应首选的方剂是","o":["麦门冬汤","沙参麦冬汤","益胃汤","百合固金汤","补肺阿胶汤"],"a":0,"e":"证属胃阴不足、气火上逆，麦门冬汤滋养肺胃、降逆下气，呕吐呃逆而舌红少苔者宜之。"},{"q":"下列哪项不属于方剂组成变化中的药味增减","o":["由麻黄汤到三拗汤","麻黄汤加白术，即麻黄加术汤","由大承气汤到小承气汤","桂枝汤加芍药，即桂枝加芍汤","抵当汤与抵当丸"],"a":4,"e":"抵当汤与抵当丸药味相同，仅改汤为丸、调整剂量，属剂型变化；药味增减须见组成药物增损。"},{"q":"患者腰脊疼痛，不能转侧，舌淡苔白，脉浮。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":1,"e":"证属风湿在表、经络痹阻，羌活胜湿汤祛风胜湿止痛，腰脊疼痛不能转侧而脉浮者宜之。"},{"q":"患者下利日数十行，谷不化，腹中雷鸣，心下痞硬而满，干呕，心烦不得安，治疗应选用","o":["小柴胡汤","甘草泻心汤","大陷胸汤","大柴胡汤","半夏泻心汤"],"a":1,"e":"证属脾胃气虚、寒热错杂，甘草泻心汤益气和胃、消痞止利，以谷不化、腹中雷鸣、下利频作为要点。"},{"q":"患者偏正头痛或巅顶头痛，恶寒发热，目眩鼻塞，舌苔薄白，脉浮。治疗首选的方剂是","o":["麻黄汤","川芎茶调散","天麻钩藤饮","半夏白术天麻汤","杏苏散"],"a":1,"e":"证属外感风邪头痛，川芎茶调散疏风止痛，偏正头痛或巅顶痛兼恶寒发热、脉浮者宜之。"},{"q":"柴葛解肌汤的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热，喘咳，苔黄，脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":2,"e":"柴葛解肌汤主治太阳阳明合病，以发热重、恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪为辨证要点。"},{"q":"麻黄杏仁甘草石膏汤的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热，喘咳，苔黄，脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":1,"e":"麻杏石甘汤主治邪热壅肺，以发热、喘咳、苔黄、脉数为辨证要点，治当辛凉宣泄、清肺平喘。"},{"q":"患者，男，65岁。腹痛便秘，胁下偏痛，畏寒肢冷，手足不温，苔白腻，脉弦紧。医生选用具有温里散寒、通便止痛功用的方剂治疗，该方是","o":["温脾汤","大黄附子汤","三物备急丸","济川煎","麻子仁丸"],"a":1,"e":"证属寒积里实，大黄附子汤温里散寒、通便止痛，腹痛便秘而畏寒肢冷、脉弦紧者宜之。"},{"q":"患者鸡鸣泄泻，伴有不思饮食，食不消化，腹痛喜温，腰酸肢冷，神疲乏力，舌淡，苔薄白，脉沉迟无力。治疗首选的方剂是","o":["理中丸","四神丸","参苓白术散","真人养脏汤","桃花汤"],"a":1,"e":"证属脾肾阳虚、肠失固摄，四神丸温肾暖脾、固肠止泻，五更泄泻、腰酸肢冷者宜之。"},{"q":"患者汗出恶风，身重微肿，肢节疼痛，小便不利，舌淡苔白，脉浮。治疗应首选的治法是","o":["益气健脾，祛湿利水","利水消肿，益气通阳","利水消肿，理气健脾","益气祛风，健脾利水","益气健脾，祛寒除湿"],"a":3,"e":"证属表虚不固、水湿内停，防己黄芪汤益气祛风、健脾利水，汗出恶风、身重微肿者宜之。"},{"q":"银翘散的辨证要点是","o":["咳嗽，发热不甚，微渴，脉浮数","发热、喘咳、苔黄、脉数","发热重， 恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪","发热，微恶寒，咽痛，口渴，脉浮数","疹发不出或出而不畅，舌红，脉数"],"a":3,"e":"银翘散主治温病初起、邪在卫分，以发热、微恶风寒、咽痛、口渴、脉浮数为辨证要点。"},{"q":"患者，大热渴饮，四肢抽搐，或厥逆，舌绛唇焦，脉沉细而数。治疗应首选的方剂是","o":["紫雪","至宝丹","白虎加人参汤","白虎加桂枝汤","清瘟败毒饮"],"a":4,"e":"证属气血两燔、热毒充斥，清瘟败毒饮清热解毒、凉血泻火，大热渴饮兼抽搐、舌绛唇焦者宜之。"},{"q":"患者居住海边，双膝关节疼痛反复发作，屈伸不利，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"证属风寒湿痹日久、肝肾气血亏虚，独活寄生汤祛风湿、止痹痛、益肝肾、补气血。"},{"q":"患者恶寒发热，头身疼痛，无汗而喘，舌苔薄白，脉浮紧。治疗应首选的方剂是","o":["麻黄汤","败毒散","桂枝汤","小青龙汤","大青龙汤"],"a":0,"e":"证属外感风寒表实证，麻黄汤发汗解表、宣肺平喘，无汗而喘、脉浮紧为其要点。"},{"q":"患者神思恍惚，心悸易惊，失眠健忘，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","甘麦大枣汤","养心汤"],"a":4,"e":"证属气血不足、心神失养，养心汤益气补血、养心安神，心悸易惊、失眠健忘而脉细弱者宜之。"},{"q":"患者头痛身热，微恶风寒，咳嗽，咽痛，口渴，舌尖红，苔薄白，脉浮数。治疗宜首选的方剂是","o":["麻黄杏仁甘草石膏汤","柴葛解肌汤","银翘散","升麻葛根汤","葱豉桔梗汤"],"a":2,"e":"证属温病初起、邪郁卫分，银翘散辛凉透表、清热解毒，发热微恶风寒、咽痛口渴、脉浮数者宜之。"},{"q":"患者因稳定型心绞痛就诊，自诉常觉胸骨后痛，偶有心慌心悸，舌质黯红，脉涩。治疗应首选的方剂是","o":["生化汤","温经汤","桃核承气汤","血府逐瘀汤","小承气汤"],"a":3,"e":"证属胸中血瘀、气机不畅，血府逐瘀汤活血化瘀、行气止痛，胸痛有定处、舌黯脉涩者宜之。"},{"q":"症见咯痰不爽，涩而难出，咽喉干燥，苔白而干等，治宜选用","o":["二陈汤","贝母瓜萎散","平胃散","大定风珠","镇肝熄风汤"],"a":1,"e":"证属燥痰咳嗽、肺燥津伤，贝母瓜蒌散润肺清热、理气化痰，痰黏难咯、咽干苔白而干者宜之。"},{"q":"患者上中二焦火热证而见有咽痛吐衄，便秘溲赤，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["凉膈散","玉女煎","泻心汤","白虎汤","清胃散"],"a":0,"e":"证属热聚胸膈、上中二焦火盛，凉膈散泻火通便、清上泄下，咽痛吐衄兼便秘溲赤者宜之。"},{"q":"患者，男，62岁。咳嗽气急，昼轻夜重，咯痰量大，痰色黄质黏，易咯出，咽干，食少难消，舌红苔厚，脉弦滑。治疗宜选的方剂是","o":["苓甘五味姜辛汤加黄芩、桑白皮","苏子降气汤加黄芩","小青龙汤加桑白皮","三子养亲汤黄芩、桑白皮","定喘汤"],"a":3,"e":"证属痰壅食滞兼肺热，三子养亲汤降气化痰消食，加黄芩、桑白皮清泄肺热，痰黄黏、苔厚脉滑者宜之。"},{"q":"患者胸中痞硬，烦懊不安，欲吐不出，气上冲咽喉不得息，寸脉微浮。治疗应首选的方剂是","o":["瓜蒂散","半夏泻心汤","枳实薤白桂枝汤","半夏厚朴汤","乌梅丸"],"a":0,"e":"证属痰涎宿食壅塞胸脘、气机不通，瓜蒂散涌吐痰食，胸中痞硬、欲吐不出、寸脉微浮者宜之。"},{"q":"患者头痛，身热不甚，口渴，咽干鼻燥，干咳无痰，舌红，苔薄白而干，脉浮数而右脉大者，治宜","o":["杏苏散","清燥救肺汤","养阴清肺汤","桑杏汤","琼玉膏"],"a":3,"e":"证属外感温燥、肺阴受灼，桑杏汤清宣温燥、润肺止咳，干咳无痰、右脉大者宜之。"},{"q":"症见小便频数，尿中带血，赤涩热痛，舌红脉数，治疗宜选","o":["五苓散","槐花散","黄土汤","龙胆泻肝汤","小蓟饮子"],"a":4,"e":"证属下焦瘀热、损伤血络，小蓟饮子凉血止血、利水通淋，尿中带血、赤涩热痛者宜之。"},{"q":"患者身不甚热，干咳无痰，咽干口燥，右脉数大。治疗宜","o":["桑菊饮","桑杏汤","柴葛解肌汤","杏苏散","麻杏石甘汤"],"a":1,"e":"证属温燥伤肺、气阴受灼，桑杏汤清宣温燥、润肺止咳，身热不甚而干咳、右脉数大者宜之。"},{"q":"以“恶寒发热，热轻寒重，无汗，肢冷倦怠，舌淡苔白，脉沉无力”为辨证要点的方剂是","o":["九味羌活汤","麻黄附子细辛汤","败毒散","再造散","参苏饮"],"a":3,"e":"证属阳气虚弱、外感风寒，再造散助阳益气、解表散寒，热轻寒重、肢冷倦怠、脉沉无力者宜之。"},{"q":"患者痈疽发背，溃后虚羸少气，溃疡作痛，倦怠懒言，少食乏味，自汗口干，夜寐不安，间有发热，经久不退，舌淡苔白，脉细弱。首选治疗方剂是","o":["八珍汤","普济消毒饮","內补黄芪汤","阳和汤","黄连解毒汤"],"a":2,"e":"证属气血两虚、余毒未尽，内补黄芪汤补益气血、生肌敛疮，疮疡溃后虚羸、久不收口者宜之。"},{"q":"以身热微寒，咽干口燥，舌红，苔薄白，脉数为辨证要点的方剂是","o":["葱白七味饮","加减葳蕤汤","葱豉汤","银翘散","桑菊饮"],"a":1,"e":"证属素体阴虚、外感风热，加减葳蕤汤滋阴解表，以身热微寒、咽干口燥、舌红脉数为要点。"},{"q":"患者皮肤疹出色红，或遍身云片斑点，瘙痒，抓破后渗出津水，苔白或黄，脉浮数。治疗首选的方剂是","o":["仙方活命饮","普济消毒饮","五味消毒饮","消风散","玉真散"],"a":3,"e":"证属风湿热邪郁于肌肤，消风散疏风除湿、清热养血，风疹湿疹瘙痒、抓破渗水者宜之。"},{"q":"患者小腹急结，小便不利，谵语狂躁，至夜发热，脉沉实而涩。治疗应首选的方剂是","o":["失笑散","温经汤","桃核承气汤","复元活血汤","生化汤"],"a":2,"e":"证属下焦蓄血、瘀热互结，桃核承气汤破血下瘀、泻热，少腹急结、谵语狂躁、脉沉实而涩者宜之。"},{"q":"患者腹痛时作，常自吐蛔，甚或手足厥冷烦闷呕吐，时发时止。治疗应首选的方剂是","o":["四逆散","理中丸","当归四逆汤","乌梅丸","肥儿丸"],"a":3,"e":"证属寒热错杂之蛔厥，乌梅丸温脏安蛔，腹痛时作、吐蛔、手足厥冷而时发时止者宜之。"},{"q":"患者下利清水，色纯青，其气臭秽，脐腹疼痛，按之坚硬有块，口舌干燥，脉滑实。医生选用大承气汤治疗，体现的中医治法是","o":["塞因塞用","通因通用","缓则治其本","标本兼治","实则泻其子"],"a":1,"e":"燥屎内结而见下利清水臭秽，属热结旁流，以承气汤泻下，为“通因通用”之典型。"},{"q":"患者温疟而见有身无寒但热，骨节疼烦，时呕，脉如平。治疗应首选的方剂是","o":["凉膈散","白虎汤","柴葛解肌汤","白虎加苍术汤","白虎加桂枝汤"],"a":4,"e":"证属里热炽盛兼表寒未解之温疟，白虎加桂枝汤清热通络，身无寒但热、骨节疼烦者宜之。"},{"q":"桂枝汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":1,"e":"桂枝汤主治外感风寒表虚、营卫不和，以恶风、发热、汗出、脉浮缓为辨证要点。"},{"q":"患者咳唾涎沫，短气喘促，咽喉干燥，舌红少苔，脉虚数。治疗宜","o":["养阴清肺汤","清燥救肺汤","桑杏汤","琼玉膏","麦门冬汤"],"a":4,"e":"证属肺胃阴虚、虚火上逆，麦门冬汤滋养肺胃、降逆下气，咳唾涎沫、短气喘促而舌红少苔者宜之。"},{"q":"患者腹痛便脓血，赤白相兼，里急后重，肛门灼热，小便短赤，舌红苔黄，脉弦数。治疗应首选的方剂是","o":["香连丸","凉膈散","黄龙汤","芍药汤","黄芩汤"],"a":3,"e":"证属湿热壅滞大肠、气血失调，芍药汤清热燥湿、调气和血，便脓血、里急后重者宜之。"},{"q":"患者怔忡不宁，或夜寐不安，口舌生疮。治疗应首选的方剂是","o":["黄连阿胶汤","磁朱丸","天王补心丹","交泰丸","酸枣仁汤"],"a":3,"e":"证属心火偏亢、肾阳不足、心肾不交，交泰丸交通心肾、引火归元，怔忡不寐、口舌生疮者宜之。"},{"q":"患者烦躁口渴，面赤唇焦，胸膈烦热，口舌生疮，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["清胃散","导赤散","左金丸","凉膈散","泻心汤"],"a":3,"e":"证属热聚胸膈，凉膈散泻火通便、清上泄下，胸膈烦热、口舌生疮、脉滑数者宜之。"},{"q":"患者恶寒发热，热轻寒重，无汗肢冷，倦怠嗜卧，面色苍白，语声低微，舌淡苔白，脉沉无力。治疗应首选的方剂是","o":["九味羌活汤","再造散","麻黄附子细辛汤","败毒散","参苏饮"],"a":1,"e":"证属阳气虚衰、外感风寒，再造散助阳益气、解表散寒，阳虚感寒而脉沉无力者宜之。"},{"q":"患者心烦不寐，口渴欲饮，小便不利，溺时涩痛，点滴难出，舌红苔微黄，脉细数。本证的病机是","o":["湿热互结，气化不利","水热互结，气化不利","痰热互结，气化不利","痰瘀互结，气化不利","瘀热互结，气化不利"],"a":1,"e":"猪苓汤证为水热互结、气化不利，水停而热伤阴津，故小便不利兼心烦口渴、舌红脉细数。"},{"q":"患者见瘰疬痰核，咽干，舌红，脉弦滑略数。首选治疗方剂是","o":["托里消毒散","消瘰丸","四妙勇安汤","苇茎汤","西黄丸"],"a":1,"e":"证属痰火凝结，消瘰丸清热化痰、软坚散结，瘰疬痰核而咽干、舌红、脉弦滑略数者宜之。"},{"q":"患者胸膈满闷，上气喘急，心下痞满，不思饮食，苔白，脉弦，治宜选用","o":["越鞠丸","柴胡疏肝散","四磨汤","枳实消痞丸","厚朴温中汤"],"a":2,"e":"证属七情所伤、肝气郁结、气逆不降，四磨汤行气降逆、宽胸散结，气逆喘急、心下痞满者宜之。"},{"q":"患者壮热面赤，烦渴引饮，汗出恶热，背微恶寒，脉浮大而芤。治疗应首选的方剂是","o":["凉膈散","白虎汤","银翘散","白虎加人参汤","白虎加桂枝汤"],"a":3,"e":"证属气分热盛、气津两伤，白虎加人参汤清热益气生津，背微恶寒、脉浮大而芤为其要点。"},{"q":"妇人漏下不止，入暮发热，手心烦热，唇干舌燥，小腹冷痛，舌黯红，脉细涩。治疗应首选的方剂是","o":["失笑散","温经汤","桃核承气汤","复元活血汤","生化汤"],"a":1,"e":"证属冲任虚寒、瘀血阻滞，温经汤温经散寒、养血祛瘀，漏下不止兼小腹冷痛、脉细涩者宜之。"},{"q":"患者牙痛，烦热干渴，舌红苔黄而干。治疗应首选的方剂是","o":["白虎汤","玉女煎","玉液汤","麦门冬汤","百合固金汤"],"a":1,"e":"证属胃热阴虚、虚火上炎，玉女煎清胃热、滋肾阴，牙痛烦热、舌红苔黄而干者宜之。"},{"q":"患者钮某，食欲不振，脘腹冷痛，口水较多，时欲呕吐，大便稀溏，口不渴，舌苔白，脉沉迟。治宜选用","o":["桂枝人参汤","温脾汤","理中丸","吴茱萸汤","大建中汤"],"a":2,"e":"证属脾胃虚寒、运化失职，理中丸温中祛寒、补气健脾，脘腹冷痛、便溏、脉沉迟者宜之。"},{"q":"患者常悲伤欲哭，不能自主，心中烦乱，睡眠不安，甚则言行失常，呵欠频作，舌淡红苔少，脉细略数。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","甘麦大枣汤","养心汤"],"a":3,"e":"证属脏阴不足、心神失养之脏躁，甘麦大枣汤养心安神、和中缓急，悲伤欲哭、呵欠频作者宜之。"},{"q":"患者上腹部疼痛2天，查体见心下至少腹硬满疼痛而痛不可近，大便秘结，日晡潮热，舌燥而渴，脉沉紧，按之有力。宜选用的方剂是","o":["大承气汤","大陷胸汤","大柴胡汤","大秦艽汤","大建中汤"],"a":1,"e":"证属水热互结之结胸，大陷胸汤泻热逐水，心下至少腹硬满、痛不可近、脉沉紧者宜之。"},{"q":"以发热重，恶寒轻，头痛，眼眶痛，鼻干，脉浮微洪为辨证要点的方剂是","o":["麻黄杏仁甘草石膏汤","银翘散","升麻葛根汤","桑菊饮","柴葛解肌汤"],"a":4,"e":"柴葛解肌汤主治太阳阳明合病，以发热重、恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪为要点。"},{"q":"患者，男，25岁，正值盛暑前来就诊，症见身热烦渴，小便不利。临床辨证为","o":["暑湿证","气分热盛证","暑热气津两伤证","外感风热，邪热壅肺证","风温初起，邪客肺络证"],"a":0,"e":"六一散主治暑湿证，暑湿伤中、湿热内蕴，故身热烦渴、小便不利或泄泻。"},{"q":"患者，男，55岁。大便不通8天，脘腹胀满疼痛，舌黄厚而干，脉沉数有力。医生用大承气汤治疗，方中厚朴的作用是","o":["行气消胀除满","泻热通便","下气开痞散结","行气通便","软坚散结"],"a":0,"e":"大承气汤中厚朴苦温行气，专于消胀除满，与枳实相配通降腑气，助大黄、芒硝泻下燥屎。"},{"q":"患者肠痈初起。右下腹疼痛拒按，局部肿痞，善屈右足，牵则剧痛，时时发热，自汗恶寒，舌苔薄黄而腻，脉滑数。首选治疗方剂是","o":["大黄牡丹汤","苇茎汤","透脓散","小金丹","牛蒡解肌汤"],"a":0,"e":"证属湿热瘀滞、肠络壅阻之肠痈初起，大黄牡丹汤泻热破瘀、散结消肿，右少腹拒按者宜之。"},{"q":"患者目赤肿痛，烦躁易怒，不能安卧，尿赤便秘，脉洪实。治疗应首选的方剂是","o":["凉膈散","左金丸","逍遥散","泻青丸","泻黄散"],"a":3,"e":"证属肝经郁火，泻青丸清肝泻火，目赤肿痛、烦躁易怒、尿赤便秘、脉洪实者宜之。"},{"q":"患者心腹剧痛，或产后恶露不行，或月经不调，小腹急痛。治疗应首选的方剂是","o":["复元活血汤","桂枝茯苓丸","失笑散","生化汤","温经汤"],"a":2,"e":"证属瘀血停滞，失笑散活血祛瘀、散结止痛，心腹剧痛及产后恶露不行者宜之。"},{"q":"患者身热心烦，口渴欲饮，恶心呕吐，小便不利，点滴难出，小腹满痛，舌红苔微黄，脉细数。治疗应首选的治法是","o":["利水渗湿，清热生津","利水渗湿，清热泻火","利水渗湿，温阳化气","利水渗湿，清热除烦","利水渗湿，养阴清热"],"a":4,"e":"猪苓汤证为水热互结而阴津受伤，故治法利水渗湿、养阴清热，利水而不伤阴。"},{"q":"患者，男，58岁。有慢性肾炎病史。因气温突降，受凉感冒2天，现恶寒发热，无汗，头身疼痛，头面四肢浮肿，舌苔白滑，脉浮。可用下列何方加味治疗","o":["香苏散","葱豉桔梗汤","九味羌活汤","小青龙汤","败毒散"],"a":3,"e":"证属外寒引动内饮之溢饮，小青龙汤解表散寒、温肺化饮，水肿兼咳喘、苔白滑者宜之。"},{"q":"患者，心腹作痛，连及腰胁，上下攻刺，经侯不调，宜用","o":["延胡索汤","天台乌药散","橘核丸","暖肝煎","加味乌药汤"],"a":0,"e":"证属气滞血瘀，延胡索汤行气活血、调经止痛，心腹作痛连及腰胁、经候不调者宜之。"},{"q":"患者发热无汗，口渴欲饮，一身面目俱黄，黄色鲜明如橘子色，小便黄赤，舌红苔黄腻，脉沉数。治疗应首选的治法是","o":["健脾利湿退黄","解表清热退黄","清热解毒退黄","清热利湿退黄","温阳利湿退黄"],"a":3,"e":"证属湿热黄疸之阳黄，茵陈蒿汤清利湿热退黄，黄色鲜明、小便短赤、苔黄腻者宜之。"},{"q":"症见癫狂惊悸，或怔忡昏迷，或咳喘痰稠，或胸脘痞闷，或眩晕耳鸣，或绕项结核，或口眼蠕动，或不寐，或梦寐奇怪之状，或骨节卒痛难以名状，或噎息烦闷。大便秘结，舌苔黄腻，脉滑数有力。治宜选用","o":["温胆汤","二陈汤","小陷胸汤","苓甘五味姜辛汤","滚痰丸"],"a":4,"e":"证属实热老痰胶结，滚痰丸泻火逐痰，癫狂惊悸、咳喘痰稠、苔黄腻、脉滑数有力者宜之。"},{"q":"患者下肢疼痛剧烈，步态不稳，舌质黯红，舌下络脉黑紫迂曲。治疗应首选的方剂是","o":["膈下逐瘀汤","血府逐瘀汤","身痛逐瘀汤","复元活血汤","生化汤"],"a":2,"e":"证属瘀血阻络，身痛逐瘀汤活血行气、祛瘀通络、通痹止痛，肢体疼痛而舌黯脉涩者宜之。"},{"q":"患者，女，65岁。咳嗽，咯痰伴气促，痰多白稀，痰易咯出，受凉后明显，饮温水后稍缓，纳可，二便正常，舌质淡红胖嫩，苔白滑，脉沉缓。治疗宜选的方剂是","o":["苓甘五味姜辛汤","苏子降气汤","小青龙汤","三子养亲汤","定喘汤"],"a":0,"e":"证属寒饮停肺，苓甘五味姜辛汤温肺化饮，咳痰白稀量多、苔白滑、脉沉缓者宜之。"},{"q":"患者身热不解，无汗，咳逆气急，甚则鼻煽，口渴，舌苔薄黄，脉浮而数。治疗宜首选的方剂是","o":["麻黄杏仁甘草石膏汤","桑菊饮","柴葛解肌汤","升麻葛根汤","银翘散"],"a":0,"e":"证属邪热壅肺，麻黄杏仁甘草石膏汤辛凉宣泄、清肺平喘，汗出而喘、苔薄黄、脉浮数者宜之。"},{"q":"患者一身面目俱黄，黄色鲜明，小便短赤，舌红苔黄腻，脉沉数有力。主治病证是","o":["黄疸阳黄","湿热互结证","黄疸，热重于湿证","黄疸，湿重于热证","黄疸阴黄"],"a":0,"e":"茵陈蒿汤主治湿热黄疸之阳黄，湿热熏蒸、胆汁外溢，故身目俱黄、黄色鲜明、小便短赤。"},{"q":"患者，女，39岁。长期居住寒湿之地。症见腰、股、腿、足疼痛，手足不温，口不渴，舌淡苔白、脉细欲绝者。治宜选用","o":["当归四逆汤","四逆汤","白通汤","通脉四逆汤","四逆散"],"a":0,"e":"证属血虚寒厥、经脉不通，当归四逆汤温经散寒、养血通脉，手足不温、脉细欲绝者宜之。"},{"q":"患者咳血1周后，现血已止，但突感风寒，头痛身热，微寒无汗。治疗首选的方剂是","o":["咳血方","桑菊饮","加减葳蕤汤","葱白七味饮","归脾汤"],"a":3,"e":"证属血虚外感风寒，葱白七味饮养血解表，失血之后复感外邪、头痛身热无汗者宜之。"},{"q":"患者心下痞满，不欲饮食，倦怠乏力，大便不畅，苔腻而微黄，脉弦，宜用","o":["柴胡疏肝散","四磨汤","厚朴温中汤","枳实消痞丸","木香顺气散"],"a":3,"e":"证属脾虚气滞、寒热互结，枳实消痞丸行气消痞、健脾和胃，痞满食少、苔腻微黄者宜之。"},{"q":"患者小便不利，烦渴欲饮，甚则水入即吐，舌苔白，脉浮或缓。治疗应首选的方剂是","o":["真武汤","五苓散","六一散","猪苓汤","萆薢分清饮"],"a":1,"e":"证属膀胱气化不利、水蓄下焦，五苓散利水渗湿、温阳化气，水入即吐之水逆证宜之。"},{"q":"王冰提出的“寒之不寒，是无水也”，宜用哪一治法治疗","o":["汗法","清法","补法","消法","温法"],"a":2,"e":"“寒之不寒，是无水也”指阴液亏虚无以制火，寒药不效，当滋阴壮水，故属补法。"},{"q":"脉结代，心动悸，虚羸少气，舌光少苔，治宜选用","o":["大补阴丸","知柏地黄丸","天王补心丹","炙甘草汤","酸枣仁汤"],"a":3,"e":"证属阴血阳气俱虚、心失所养，炙甘草汤益气滋阴、通阳复脉，脉结代、心动悸者宜之。"},{"q":"患者颈项、头面红肿热痛，牙龈肿痛，寒轻热重，汗少口渴，小便黄赤，苔黄，脉浮数。首选治疗方剂是","o":["黄连解毒汤","四妙勇安汤","牛蒡解肌汤","仙方活命饮","海藻玉壶汤"],"a":2,"e":"证属风热痰毒上攻，牛蒡解肌汤疏风清热、凉血消肿，头面红肿热痛、寒轻热重者宜之。"},{"q":"脾肾虚寒，久泻久痢者，治宜选用","o":["四神丸","真人养脏汤","芍药汤","葛根芩连汤","补中益气汤"],"a":1,"e":"真人养脏汤主治脾肾虚寒、久泻久痢、滑脱不禁，功能涩肠固脱、温补脾肾。"},{"q":"患者脘腹疼痛，恶心呕吐，肠鸣泄泻，舌苔白腻，脉濡。治疗应首选的方剂是","o":["参苓白术散","痛泻要方","半夏泻心汤","理中丸","藿香正气散"],"a":4,"e":"证属外感风寒、内伤湿滞，藿香正气散解表化湿、理气和中，吐泻交作、苔白腻者宜之。"},{"q":"患者，男，50岁。便秘腹痛，脐周绞痛，畏寒肢冷，手足不温。医生选用“辛热甘温咸寒合法，寓补于攻”的方剂进行治疗，该方是","o":["大黄附子汤","温脾汤","大承气汤","小承气汤","调胃承气汤"],"a":1,"e":"证属脾阳不足、寒积内停，温脾汤以附子、大黄为君，辛热与咸寒合法，寓补于攻，温下寒积。"},{"q":"患者，女，38岁。每到冬季，两手青紫及腕际，指尖更甚，有麻冷感，遇暖则转红。西医诊断为雷诺病。曾多方医治，疗效甚微。就诊时舌淡苔白，脉沉细微。宜选择下列哪方治疗","o":["当归四逆汤","四逆汤","通脉四逆汤","白通汤","四逆散"],"a":0,"e":"证属血虚寒凝、经脉不通，当归四逆汤温经散寒、养血通脉，肢端青紫冷麻、脉沉细微者宜之。"},{"q":"患者患肢黯红微肿灼热，疼痛剧烈，久则溃烂腐臭，脚趾节脱落，延及足背，烦热口渴，舌红，脉数。首选治疗方剂是","o":["西黄丸","四妙勇安汤","五味消毒饮","阳和汤","小金丹"],"a":1,"e":"证属热毒炽盛之脱疽，四妙勇安汤清热解毒、活血止痛，患肢红肿灼热、溃烂腐臭者宜之。"},{"q":"患者症见身热汗多，口渴心烦，小便短赤，体倦少气，精神不振，脉虚数。临床辨证为","o":["暑湿证","气分热盛证","温病后期，邪伏阴分证","暑热气津两伤证","暑温证"],"a":3,"e":"清暑益气汤证系暑热耗气伤津，故身热汗多、口渴心烦、体倦少气、脉虚数，属暑热气津两伤证。"},{"q":"患者虚烦失眠，心悸不安，头目眩晕，咽干口燥，舌红，脉弦细。治疗应首选的方剂是","o":["朱砂安神丸","天王补心丹","酸枣仁汤","甘麦大枣汤","养心汤"],"a":2,"e":"证属肝血不足、虚热内扰，酸枣仁汤养血安神、清热除烦，虚烦失眠、脉弦细者宜之。"},{"q":"葱豉桔梗汤的辨证要点是","o":["头痛身热、咳嗽、咽痛、口渴、脉浮数","发热、喘咳、苔黄、脉数","发热重、恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪","发热、微恶寒、咽痛、口渴、脉浮数","疹发不出或出而不畅、舌红、脉数"],"a":0,"e":"葱豉桔梗汤主治风温初起、邪客肺卫，以头痛身热、微恶风寒、咳嗽咽痛、口渴、脉浮数为要点。"},{"q":"患者，热入营分而见身热夜甚，时有谵语，口渴或不渴，目常喜开或喜闭，舌绛而干，脉细数。治疗应首选的方剂是","o":["清骨散","清营汤","青蒿鳖甲汤","秦艽鳖甲散","清瘟败毒饮"],"a":1,"e":"证属热入营分、营热阴伤，清营汤清营解毒、透热养阴，身热夜甚、舌绛而干、脉细数者宜之。"},{"q":"患者气喘咳嗽，皮肤蒸热，日晡尤甚，舌红苔黄，脉细数。治疗应首选的方剂是","o":["定喘汤","泻白散","导赤散","止嗽散","麻黄杏仁甘草石膏汤"],"a":1,"e":"证属肺有伏火、阴分受伤，泻白散清泻肺热、止咳平喘，皮肤蒸热、日晡尤甚者宜之。"},{"q":"患者脘腹胀满，不思饮食，舌苔白腻，脉沉弦，宜选用","o":["理中丸","藿香正气散","枳实消痞丸","半夏泻心汤","厚朴温中汤"],"a":4,"e":"证属寒湿困中、气机阻滞，厚朴温中汤行气除满、温中燥湿，脘腹胀满、苔白腻、脉沉弦者宜之。"},{"q":"患者症见身热汗多，口渴心烦，小便短赤，体倦少气，精神不振，脉虚数。此病证的治法是","o":["清泻肺热，止咳平喘","清暑利湿","清暑益气，养阴生津","祛暑解表，化湿和中","益气生津，敛阴止汗"],"a":2,"e":"清暑益气汤证为暑热耗气伤津，治法清暑益气、养阴生津，属清补兼施。"},{"q":"患者三焦火毒热盛证而见有湿热黄疸，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["茵陈蒿汤","栀子柏皮汤","黄连解毒汤","普济消毒饮","甘露消毒丹"],"a":2,"e":"证属三焦火毒热盛，黄连解毒汤泻火解毒，火折则湿热黄疸自退，舌红苔黄、脉数有力者宜之。"},{"q":"患者见寒热如疟，寒轻热重，口苦膈闷，吐酸苦水，胸胁胀痛，小便黄少，舌红苔黄腻，脉数而右滑左弦。首选方剂是","o":["逍遥散","小柴胡汤","茵陈蒿汤","龙胆泻肝汤","蒿芩清胆汤"],"a":4,"e":"证属少阳湿热痰浊，蒿芩清胆汤清胆利湿、和胃化痰，寒热如疟、口苦膈闷、苔黄腻者宜之。"},{"q":"患者恶寒身热，头痛无汗，胸脘痞闷，不思饮食，舌苔薄白，脉浮。治疗应自选的方剂是","o":["桂枝汤","香苏散","大青龙汤","败毒散","九味羌活汤"],"a":1,"e":"证属外感风寒、内有气滞，香苏散疏风散寒、理气和中，胸脘痞闷、不思饮食者宜之。"},{"q":"患者咳嗽气喘，咽喉干燥，喉中有声，痰中带血，舌红少苔，脉细数。治宜","o":["百合固金汤","桑杏汤","清燥救肺汤","补肺阿胶汤","玉液汤"],"a":3,"e":"证属肺虚火盛、气阴耗伤，补肺阿胶汤养阴补肺、清热止咳，咳喘痰中带血、脉细数者宜之。"},{"q":"症见久泻不愈，不思饮食，食不消化，腹痛喜温，腰酸肢冷，神疲乏力，舌淡，苔薄白，脉沉迟无力者。治宜首选","o":["真人养脏汤","肾气丸","桃花汤","四神丸","芍药汤"],"a":0,"e":"证属脾肾虚寒、滑脱不禁，真人养脏汤涩肠固脱、温补脾肾，久泻久痢而无五更特征者宜之。"},{"q":"症见痔疮出血，血色鲜红，舌红苔黄，脉数，治宜选用","o":["胶艾汤","归脾汤","黄土汤","槐花散","葛根芩连汤"],"a":3,"e":"证属肠风脏毒下血，槐花散清肠止血、疏风行气，痔血鲜红、舌红苔黄、脉数者宜之。"},{"q":"患者小便频数，淋沥不畅，溺时涩痛，小腹急满，舌苔黄腻，脉滑数。本证的病机是","o":["瘀热下注，蕴于膀胱","寒湿下注，蕴于膀胱","热毒下注，蕴于膀胱","暑湿下注，蕴于膀胱","湿热下注，蕴于膀胱"],"a":4,"e":"八正散证病机为湿热下注、蕴结膀胱，膀胱气化不利，故尿频淋沥涩痛、小腹急满。"},{"q":"妇人素有癥块，妊娠漏下不止，血色紫黑晦黯，舌质紫黯或有瘀点，脉沉涩者。治宜首选","o":["血府逐瘀汤","复元活血汤","生化汤","温经汤","桂枝茯苓丸"],"a":4,"e":"证属瘀血癥块阻滞胞宫，桂枝茯苓丸活血化瘀、缓消癥块，素有癥块而妊娠漏下者宜之。"},{"q":"以恶寒发热，无汗，烦躁，脉浮紧为辨证要点的方剂是","o":["麻黄汤","大青龙汤","桂枝汤","败毒散","小青龙汤"],"a":1,"e":"大青龙汤主治外感风寒、内有郁热，以恶寒发热、无汗、烦躁、脉浮紧为辨证要点。"},{"q":"患者心中烦热，失眠不得卧，口燥咽干，舌红苔少，脉细数。治疗应首选的方剂是","o":["朱砂安神丸","黄连阿胶汤","酸枣仁汤","桂枝甘草龙骨牡蛎汤","交泰丸"],"a":1,"e":"证属阴虚火旺、心肾不交，黄连阿胶汤滋阴降火、除烦安神，心烦不寐、舌红苔少者宜之。"},{"q":"患者，男，50岁。便秘腹痛，脐周绞痛，畏寒肢冷，手足不温。医生选用温脾汤治疗，该方的君药是","o":["干姜、大黄","附子、干姜","大黄、芒硝","干姜、人参","附子、大黄"],"a":4,"e":"温脾汤以附子温补脾阳、大黄泻下寒积，二药共为君药，体现温下兼补之法。"},{"q":"患者，男，35岁。发狂2月，语无伦次，近10天病情加重，性情急躁，两目怒视，狂乱无知，不避亲疏，弃衣欲走，叫喊不已，大便秘结，脉象浮滑洪紧，舌苔黄燥。治宜选用的方剂是","o":["朱砂安神丸","镇肝熄风汤","大承气汤","桃核承气汤","酸枣仁汤"],"a":2,"e":"证属阳明腑实、浊热上扰神明，大承气汤峻下热结，燥屎去则神志自清，狂乱便结者宜之。"},{"q":"患者猝然心腹疼痛，牙关紧闭，昏仆不醒，急救应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","苏合香丸","紫金锭"],"a":3,"e":"证属寒邪秽浊闭阻气机之寒闭，苏合香丸芳香开窍、行气止痛，猝然昏仆、牙关紧闭者宜之。"},{"q":"患者，男，30岁。平素喜食火锅，现感冒1天，症见恶寒发热，无汗，头痛项强，肢体酸楚疼痛，口苦口渴，舌苔黄，脉浮紧。可用下列何方加味治疗","o":["大青龙汤","九味羌活汤","麻黄杏仁甘草石膏汤","白虎汤","败毒散"],"a":1,"e":"证属外感风寒湿邪兼内有蕴热，九味羌活汤发汗祛湿、兼清里热，口苦口渴、苔黄者宜之。"},{"q":"以头痛身热，恶寒无汗兼见血虚或有失血病史为辨证要点的方剂是","o":["当归补血汤","桑菊饮","加减葳蕤汤","葱白七味饮","归脾汤"],"a":3,"e":"葱白七味饮主治血虚外感风寒，以头痛身热、恶寒无汗兼血虚或失血病史为辨证要点。"},{"q":"患者，男，43岁。证见脘腹痞满胀痛，嗳腐吞酸，恶食呕逆，伴大便泄泻，舌苔厚腻，脉滑。治宜","o":["木香槟榔丸","葛花解酲汤","保和丸","枳实导滞丸","健脾丸"],"a":2,"e":"证属食积内停、胃失和降，保和丸消食和胃，嗳腐吞酸、恶食呕逆、苔厚腻者宜之。"},{"q":"症见尿频、遗尿，心神恍惚，健忘，舌淡苔白，脉细弱，治宜选","o":["桑螵蛸散","归脾汤","萆薢分清饮","缩泉丸","天王补心丹"],"a":0,"e":"证属肾虚不摄、心肾两虚，桑螵蛸散调补心肾、涩精止遗，尿频遗尿兼心神恍惚健忘者宜之。"},{"q":"患者突然耳聋，伴有口苦，目赤，耳肿，舌红苔黄，脉弦数有力。治疗应首选的方剂是","o":["清胃散","凉膈散","六味地黄丸","龙胆泻肝汤","黄连解毒汤"],"a":3,"e":"证属肝胆实火上炎，龙胆泻肝汤清泻肝胆实火、清利湿热，暴聋耳肿、口苦目赤者宜之。"},{"q":"患者，男，23岁。大便不通7天，兼见频转矢气，脘腹痞满，腹痛拒按，手足濈然汗出，舌苔黄燥，脉沉实。医生主张用“苦辛通降与咸寒合法，泻下与行气并重”的方剂治疗，此方是","o":["小承气汤","大承气汤","温脾汤","黄龙汤","调胃承气汤"],"a":1,"e":"证属阳明腑实、痞满燥实俱全，大承气汤峻下热结，泻下与行气并重，苦辛通降与咸寒合法。"},{"q":"患者恶寒发热，头项强痛，肢体酸痛，无汗，鼻塞声重，咳嗽有痰，胸膈痞满，舌淡苔白，脉浮而按之无力。治疗应首选的方剂是","o":["九味羌活汤","葱白七味饮","再造散","败毒散","参苏饮"],"a":3,"e":"证属正气不足、外感风寒湿邪，败毒散益气解表、散寒祛湿，脉浮而按之无力为其要点。"},{"q":"患者，大头瘟。治疗应首选的方剂是","o":["五味消毒饮","仙方活命饮","普济消毒饮","黄连解毒汤","清瘟败毒饮"],"a":2,"e":"证属风热疫毒壅于上焦之大头瘟，普济消毒饮清热解毒、疏风散邪。"},{"q":"患者，女，32岁。发病3年，手足厥冷，但不过膝、不过肘，面色㿠白，口不渴，舌淡苔白，脉沉细。宜选择下列哪方治疗","o":["吴茱萸汤","小建中汤","当归四逆汤","四逆汤","大建中汤"],"a":2,"e":"证属血虚寒凝，当归四逆汤温经散寒、养血通脉，手足厥冷不过肘膝、脉沉细者宜之。"},{"q":"患者，男。运动后吹风，感冒1天。现体温39.5℃，怕风，无汗，口渴头痛，咽痛咳嗽，舌尖红，苔薄黄，脉浮数。可用下列何方加减治疗","o":["桑菊饮","银翘散","柴葛解肌汤","升麻葛根汤","麻黄杏仁甘草石膏汤"],"a":1,"e":"证属温病初起、邪在卫分，银翘散辛凉透表、清热解毒，发热咽痛、舌尖红、脉浮数者宜之。"},{"q":"患者身重疼痛，肢体倦怠，胸闷不饥，午后身热，苔白不渴，脉弦细而濡。本证的病机是","o":["热重于湿，脾胃失和","湿重于热，脾胃失和","湿热并重，脾胃失和","湿热困脾，升降失常","寒湿困脾，升降失常"],"a":1,"e":"三仁汤证为湿温初起、湿重于热、脾胃失和，湿遏卫阳，故身重疼痛、午后身热、苔白不渴、脉濡。"},{"q":"患者，男，67岁。咽痒咳嗽，甚则伴喘，痰多色白清稀，纳可，时有心悸，苔白，脉紧而弦。治疗应首选的方剂是","o":["苓甘五味姜辛汤","止嗽散","小青龙汤","苏子降气汤","二陈汤"],"a":0,"e":"证属寒饮停肺，苓甘五味姜辛汤温肺化饮，咳喘痰白清稀、遇寒加重、苔白、脉紧弦者宜之。"},{"q":"患者男，吹风后感冒1天。现头痛身热，微恶风寒，咳嗽，咽痛，口渴，舌尖红，苔薄白，脉浮数。治疗可用下列何方加减治疗","o":["银翘散","葱豉桔梗汤","麻黄杏仁甘草石膏汤","柴葛解肌汤","升麻葛根汤"],"a":1,"e":"葱豉桔梗汤主治风温初起、邪客肺卫，以头痛身热、微恶风寒、咳嗽咽痛、舌尖红、脉浮数为要点。"},{"q":"患者少腹瘀血积块，疼痛，经期腰酸，久不受孕。治疗应首选的方剂是","o":["失笑散","少腹逐瘀汤","桃核承气汤","复元活血汤","生化汤"],"a":1,"e":"证属寒凝血瘀于少腹，少腹逐瘀汤活血祛瘀、温经止痛，少腹积块疼痛、久不受孕者宜之。"},{"q":"患者汗多神疲，体倦乏力，气短懒言，咽干口渴，干咳少痰，短气自汗，治疗宜用的方剂是","o":["生脉散","肾气丸","补中益气汤","归脾汤","四物汤"],"a":0,"e":"证属气阴两伤，生脉散益气生津、敛阴止汗，汗多神疲、气短懒言、咽干口渴者宜之。"},{"q":"患者，女，35岁。证见食少难消，脘腹痞满，大便溏薄，倦怠乏力，苔腻微黄，脉虚弱。宜选","o":["保和丸","枳术丸","温脾汤","归脾丸","健脾丸"],"a":4,"e":"证属脾虚食积兼有湿热，健脾丸健脾和胃、消食止泻，食少难消、便溏、苔腻微黄者宜之。"},{"q":"患者胸胁满闷，目眩心悸，舌苔白滑，脉弦滑。治疗应首选的方剂是","o":["十枣汤","苓桂术甘汤","龙胆泻肝汤","柴胡疏肝散","苏子降气汤"],"a":1,"e":"证属中阳不足、痰饮内停，苓桂术甘汤温阳化饮、健脾利湿，胸胁满闷、目眩心悸、苔白滑者宜之。"},{"q":"患者，女，66岁。眼睑痉挛不适1年余。现症见眼睑痉挛，面肌搐抖，下颌抽动，似嚼食物，口干口苦，纳少寐差，大便不畅，舌质红，苔黄腻，脉弦滑。治疗应首选的方剂是","o":["定痫丸","半夏白术天麻汤","龙胆泻肝汤","天麻钩藤饮","镇肝熄风汤"],"a":0,"e":"证属风痰蕴热、痰热上扰，定痫丸涤痰息风、清热定痫，面肌搐抖、苔黄腻、脉弦滑者宜之。"},{"q":"患者，男，28岁。左小腿有一处局部漫肿无头，酸痛无热，皮色不变，口不渴，舌苔淡白，脉沉细。治疗宜选用","o":["阳和汤","西黄丸","透脓散","小金丹","仙方活命饮"],"a":0,"e":"证属阳虚寒凝之阴疽，阳和汤温阳补血、散寒通滞，漫肿无头、皮色不变、脉沉细者宜之。"},{"q":"患者但咳，身热不甚，口微渴，脉浮数。治疗宜首选的方剂是","o":["升麻葛根汤","麻黄杏仁甘草石膏汤","桑菊饮","银翘散","柴葛解肌汤"],"a":2,"e":"证属风温初起、邪客肺络，桑菊饮疏风清热、宣肺止咳，但咳、身热不甚、口微渴者宜之。"},{"q":"患者素体肺肾阴虚，现咳嗽气喘，痰中带血，咽喉燥痛，头晕目眩，午后潮热，舌红少苔，脉细数。治疗宜首选的方剂是","o":["沙参麦冬汤","百合固金汤","麦门冬汤","琼玉膏","清燥救肺汤"],"a":1,"e":"证属肺肾阴虚、虚火上炎，百合固金汤滋养肺肾、止咳化痰，痰中带血、咽喉燥痛、脉细数者宜之。"},{"q":"患者，女，30岁。大便不通5天，脘腹胀满疼痛，舌黄厚而干，脉沉数有力。下列最为适宜的方剂是","o":["大陷胸汤","温脾汤","大黄附子汤","大承气汤","麻子仁丸"],"a":3,"e":"证属阳明腑实、燥屎内结，大承气汤峻下热结，痞满燥实俱全而脉沉数有力者宜之。"},{"q":"气虚血瘀之中风证，治宜选方","o":["桃核承气汤","血府逐瘀汤","小蓟饮子","槐花散","补阳还五汤"],"a":4,"e":"补阳还五汤主治气虚血瘀之中风，功能补气活血通络，半身不遂、脉缓无力者宜之。"},{"q":"患者发热，微恶风寒，无汗，口渴头痛，咽痛咳嗽，舌尖红，苔薄黄，脉浮数。治疗应首选的方剂是","o":["银翘散","桑菊饮","麻黄杏仁甘草石膏汤","柴葛解肌汤","升麻葛根汤"],"a":0,"e":"证属温病初起、邪在卫分，银翘散辛凉透表、清热解毒，发热微恶风寒、咽痛口渴、脉浮数者宜之。"},{"q":"患者胸痛，日久不愈，痛如针刺而有定处，舌质黯红，脉紧。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":3,"e":"证属胸中血瘀，血府逐瘀汤活血化瘀、行气止痛，胸痛日久如针刺有定处、舌黯脉涩者宜之。"},{"q":"患者，热入血分而见尿血、便血，舌深绛起刺，脉数。治疗应首选的方剂是","o":["小蓟饮子","槐花散","犀角地黄汤","羚角钩藤汤","大定风珠"],"a":2,"e":"证属热入血分、血热妄行，犀角地黄汤清热解毒、凉血散瘀，尿血便血、舌深绛起刺者宜之。"},{"q":"患者小便不利，脐下动悸，吐涎沫而头眩，舌苔白，脉缓。本证的病机是","o":["水热结于下焦，痰饮内停","湿热下注膀胱，痰饮内停","膀胱气化不利，痰饮内停","暑湿下注膀胱，痰饮内停","瘀热下注膀胱，痰饮内停"],"a":2,"e":"五苓散证病机为膀胱气化不利、水蓄下焦，水饮上逆则吐涎沫、头眩、脐下动悸，属痰饮内停。"},{"q":"患者反复咳喘10余年，咳甚则气喘自汗，痰少而粘，脉虚数。治宜首选","o":["生脉散","定喘汤","泻白散","九仙散","麻黄汤"],"a":3,"e":"证属久咳肺虚、气阴耗伤，九仙散敛肺止咳、益气养阴，咳甚气喘自汗、痰少而黏、脉虚数者宜之。"},{"q":"症见痰稠色黄，咯之不爽，胸膈痞闷，甚则气急呕恶，舌质红，苔黄腻，脉滑数者，治宜选用","o":["贝母瓜萎散","温胆汤","半夏白术天麻汤","苓甘五味姜辛汤","清气化痰丸"],"a":4,"e":"证属痰热内结，清气化痰丸清热化痰、理气止咳，痰稠色黄难咯、苔黄腻、脉滑数者宜之。"},{"q":"患者见恶寒发热，头疼身痛，无汗，腹痛吐泻，胸脘痞闷，舌苔白腻，脉浮，治宜首选","o":["清暑益气汤","竹叶石膏汤","香薷散","桂苓甘露散","六一散"],"a":2,"e":"证属夏月外感风寒、内伤湿滞，香薷散祛暑解表、化湿和中，恶寒无汗、腹痛吐泻者宜之。"},{"q":"治疗脏躁首选的方剂是","o":["养心汤","天王补心丹","酸枣仁汤","甘麦大枣汤","磁朱丸"],"a":3,"e":"甘麦大枣汤为治脏躁主方，功能养心安神、和中缓急，悲伤欲哭、不能自主、呵欠频作者宜之。"},{"q":"患者头痛恶寒，肢体倦怠，身重疼痛，胸闷不饥，午后身热，面色淡黄，苔白不渴，脉濡。主治病证是","o":["湿温初起之湿热并重证","暑温夹湿之热重于湿证","暑温初起之热重于湿证","湿温初起之湿重于热证","湿温初起之热重于湿证"],"a":3,"e":"三仁汤主治湿温初起、湿重于热证，湿遏卫阳、脾胃失和，故身重疼痛、胸闷不饥、苔白不渴、脉濡。"},{"q":"跌打损伤，筋断骨折之瘀血肿痛，刀伤出血，一切无名肿毒，烧伤烫伤者，治疗应选用的方剂是","o":["复元活血汤","黄土汤","槐花散","七厘散","归脾汤"],"a":3,"e":"证属跌打损伤、瘀血肿痛及出血，七厘散散瘀消肿、止痛止血，为伤科常用方。"},{"q":"患者四肢沉重疼痛，下肢浮肿，畏寒肢冷，小便不利，舌淡胖苔白滑，脉沉细。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":3,"e":"真武汤主治脾肾阳虚、水湿内泛之证，方中附子温肾助阳以化气行水，白术、茯苓健脾渗湿。苓桂术甘汤证为中阳不足、饮停心下，见胸胁支满、目眩心悸，无阳虚水肿之候。"},{"q":"以发热、喘咳、苔黄、脉数为辨证要点的方剂是","o":["银翘散","麻黄杏仁甘草石膏汤","升麻葛根汤","柴葛解肌汤","桑菊饮"],"a":1,"e":"麻黄杏仁甘草石膏汤主治外感风邪、邪热壅肺证，以发热、喘咳、苔黄、脉数为辨证要点，麻黄配石膏清宣肺热而定喘。银翘散、桑菊饮均属辛凉解表之剂，喘咳与苔黄不显。"},{"q":"将药物加水反复煎煮，去渣浓缩后，加蜜或糖炼制而成的半液体剂型属","o":["酒剂","膏剂","茶剂","露剂","丹剂"],"a":1,"e":"膏剂是将药物加水反复煎煮、去渣浓缩后加蜜或糖炼制而成的半流体剂型，内服者多为煎膏，长于滋补调理。酒剂以酒浸药，茶剂以药代茶冲泡，露剂为蒸馏所得芳香液，均非煎煮浓缩加蜜。"},{"q":"治疗太阳风寒未解，入里化热，初犯阳明或三阳合病之常用方是","o":["升麻葛根汤","柴葛解肌汤","桑菊饮","银翘散","麻黄杏仁甘草石膏汤"],"a":1,"e":"柴葛解肌汤解肌清热，主治太阳风寒未解、寒邪入里化热，初犯阳明或三阳合病，见恶寒渐轻、身热增盛、目疼鼻干、苔薄黄、脉浮微洪。升麻葛根汤专主麻疹初起，银翘散主风热表证。"},{"q":"患者类风湿性关节炎病史多年，现多关节疼痛，运动不利，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"独活寄生汤祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚、气血不足，见关节疼痛、屈伸不利、畏寒喜暖、舌淡脉细弱。羌活胜湿汤证以头身重痛为主，无正虚之候。"},{"q":"患者肠痈日久，身无热，肌肤甲错，腹皮急，按之濡如肿状，脉数。首选治疗方剂是","o":["大黄牡丹汤","西黄丸","苇茎汤","阳和汤","薏苡附子败酱散"],"a":4,"e":"薏苡附子败酱散主治肠痈日久、正虚邪恋，见身无热、肌肤甲错、腹皮急、按之濡如肿状、脉数，以薏苡仁排脓、附子温阳、败酱草解毒。大黄牡丹汤为肠痈初起、热毒壅盛者设。"},{"q":"患者肢体筋脉疼痛，麻木拘挛，关节屈伸不利，疼痛游走不定。亦治中风，手足不仁，日久不愈，经络湿痰瘀血，而见腰腿沉重，或腿臂间作痛。治疗首选的方剂是","o":["羌活胜湿汤","小活络丹","独活寄生汤","大秦艽汤","九味羌活汤"],"a":1,"e":"小活络丹祛风除湿、化痰通络、活血止痛，主治风寒湿痹日久、痰瘀阻络，见肢体筋脉疼痛、麻木拘挛、屈伸不利、疼痛游走，亦治中风手足不仁。独活寄生汤则以肝肾气血亏虚为本。"},{"q":"患者恶寒发热，头身疼痛，无汗，喘咳，痰涎清稀而量多，舌苔白滑，脉浮。治疗应自选的方剂是","o":["小青龙汤","香苏散","葱豉桔梗汤","败毒散","九味羌活汤"],"a":0,"e":"小青龙汤解表散寒、温肺化饮，主治外感风寒、内停水饮，见恶寒发热、无汗、喘咳、痰涎清稀量多、苔白滑、脉浮。九味羌活汤兼里热，香苏散主气滞感冒，皆无寒饮喘咳。"},{"q":"治疗中气虚弱，寒热互结，升降失常的基础方是","o":["生姜泻心汤","半夏泻心汤","甘草泻心汤","黄连汤","大黄附子汤"],"a":1,"e":"半夏泻心汤寒热平调、散结除痞，主治中气虚弱、寒热互结、升降失常之心下痞，为辛开苦降、调和寒热之基础方。生姜泻心汤、甘草泻心汤均在此方基础上加减而成。"},{"q":"患者汗出恶风，小便不利，舌淡苔白，脉浮。治疗应首选的方剂是","o":["导赤散","防己黄芪汤","猪苓汤","五苓散","真武汤"],"a":1,"e":"防己黄芪汤益气祛风、健脾利水，主治表虚不固之风水、风湿，见汗出恶风、小便不利、舌淡苔白、脉浮。五苓散证为膀胱气化不利之蓄水，无汗出恶风之表虚象。"},{"q":"患者筋痿，阴汗，舌红苔黄腻，脉细数有力。治疗应首选的方剂是","o":["龙胆泻肝汤","知柏地黄丸","甘露消毒丹","六味地黄丸","当归六黄汤"],"a":0,"e":"龙胆泻肝汤清泻肝胆实火、清利肝经湿热，主治肝经湿热下注之筋痿、阴汗，见舌红苔黄腻、脉细数有力。知柏地黄丸滋阴降火，用于阴虚火旺而无实火湿浊。"},{"q":"患者，女，25岁。因外出游玩，吹风后感冒1天。现怕风，发热，咳嗽咽痒，咯痰不爽，舌苔薄白，脉浮缓。可用下列何方加味治疗","o":["香苏散","九味羌活汤","败毒散","止嗽散","葱豉桔梗汤"],"a":3,"e":"止嗽散宣利肺气、疏风止咳，主治风邪犯肺之咳嗽咽痒、咯痰不爽、微恶风发热、苔薄白，药性温润平和，随证加味尤宜外感咳嗽表邪已去大半者。九味羌活汤主风寒湿表证。"},{"q":"患者反复泻利，甚至脱门坠下，伴有脐腹冷痛，喜温喜按，倦怠食少，舌淡苔白，脉迟细。治疗首选的方剂是","o":["四神丸","理中丸","真人养脏汤","桃花汤","补中益气汤"],"a":2,"e":"真人养脏汤涩肠固脱、温补脾肾，主治脾肾虚寒、久泻久痢、滑脱不禁，甚则脱肛坠下、脐腹冷痛、喜温喜按。四神丸主五更泻，补中益气汤主中气下陷而无泻痢滑脱。"},{"q":"患者，男，55岁。平素嗜酒。刻下眩晕呕吐，胸膈痞闷，食少体倦，小便不利，大便泄泻，舌苔腻，脉滑。治宜","o":["健脾丸","葛花解酲汤","木香槟榔丸","木香导滞丸","枳实消痞丸"],"a":1,"e":"葛花解酲汤分消酒湿、温中健脾，主治嗜酒伤脾、酒积内停之眩晕呕吐、胸膈痞闷、食少体倦、小便不利、大便泄泻、苔腻脉滑，方中葛花解酒醒脾。健脾丸主脾虚食积而无酒毒。"},{"q":"患者虚劳干咳，咽燥咯血，肌肉消瘦，气短乏力，舌红少苔，脉细数。治疗宜首选的方剂是","o":["麦门冬汤","百合固金汤","养阴清肺汤","琼玉膏","清燥救肺汤"],"a":3,"e":"琼玉膏滋阴润肺、益气补脾，主治虚劳肺肾阴虚，见干咳、咽燥咯血、肌肉消瘦、气短乏力、舌红少苔、脉细数。百合固金汤偏治肺肾阴虚之咳嗽痰血，麦门冬汤主虚热肺痿。"},{"q":"桑菊饮的辨证要点是","o":["咳嗽、发热不甚、微渴、脉浮数","发热、喘咳、苔黄、脉数","发热重、 恶寒轻、头痛、眼眶痛、鼻干、脉浮微洪","发热、微恶寒、咽痛、口渴、脉浮数","疹发不出或出而不畅、舌红、脉数"],"a":0,"e":"桑菊饮疏风清热、宣肺止咳，为辛凉轻剂，主治风温初起、表热轻证，辨证要点为咳嗽、发热不甚、微渴、脉浮数。发热重而咽痛口渴者属银翘散证，喘咳苔黄者属麻杏甘石汤证。"},{"q":"患者，女，53岁。患者痰多色白易咳，胸膈痞闷，恶心呕吐，肢体倦怠，舌苔白润，脉滑。选用何方为佳","o":["清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤","茯苓丸"],"a":3,"e":"二陈汤燥湿化痰、理气和中，为治湿痰之基础方，见痰多色白易咳、胸膈痞闷、恶心呕吐、肢体倦怠、苔白润、脉滑。温胆汤证痰热内扰而见胆怯易惊、苔黄腻，清气化痰丸主痰热咳嗽。"},{"q":"患者，男，30岁。头晕伴耳鸣3周。头晕如坐舟车，口苦，耳鸣，小便可，大便干，舌红苔白腻，脉弦滑。治疗应首选的方剂是","o":["温胆汤加黄芩","定痫丸加白术","天麻钩藤饮加白术","镇肝熄风汤加黄芩","半夏白术天麻汤加黄芩"],"a":4,"e":"半夏白术天麻汤化痰熄风、健脾祛湿，主治风痰上扰之眩晕头痛；头晕如坐舟车、口苦、苔白腻、脉弦滑兼胆经郁热，故加黄芩清胆热。单用温胆汤则乏健脾熄风之力。"},{"q":"患者风湿热痹，身大热，关节肿痛等。治疗应首选的方剂是","o":["小活络丹","大活络丹","当归拈痛汤","白虎加桂枝汤","白虎加苍术汤"],"a":4,"e":"官方答案为【白虎加苍术汤】，但依据教材，正确答案为【白虎加桂枝汤】。白虎加桂枝汤治温疟身无寒但热、骨节疼烦，后世列为风湿热痹之代表方，桂枝温通经络以止关节肿痛；白虎加苍术汤则主治湿温病。"},{"q":"患者下痢脓血，赤多白少，腹痛里急后重，肛门灼热，渴欲饮水，舌红苔黄，脉弦数。治疗应首选的方剂是","o":["芍药汤","桃花汤","白头翁汤","黄连解毒汤","葛根黄芩黄连汤"],"a":2,"e":"白头翁汤清热解毒、凉血止痢，主治热毒深陷血分之热毒血痢，见下痢脓血、赤多白少、腹痛里急后重、肛门灼热、舌红苔黄、脉弦数。芍药汤主湿热痢之赤白相兼、气血失调。"},{"q":"有关服药时间，如病在上焦者宜","o":["食后服","临睡服","食前服","早上空腹服","不拘时服"],"a":0,"e":"服药时间因病变部位而异，病在上焦者宜食后服，使药力留于上焦；病在下焦者宜食前服，病在四肢血脉者宜空腹服，病在骨髓者宜临卧服。"},{"q":"患者胸中满痛彻背，背痛彻胸，不能安卧者，宜用","o":["丹参饮","瓜蒌薤白白酒汤","瓜蒌薤白半夏汤","枳实薤白桂枝汤","血府逐瘀汤"],"a":2,"e":"瓜蒌薤白半夏汤通阳散结、祛痰宽胸，主治胸痹痰浊壅盛，见胸中满痛彻背、背痛彻胸、不得安卧，方中半夏增强化痰降逆之力。瓜蒌薤白白酒汤证痰浊较轻，仅见喘息咳唾、胸背痛。"},{"q":"患者遍身水肿，喘呼气急，烦躁口渴，二便不利，脉沉实。治疗应首选的方剂是","o":["小青龙汤","麻黄杏仁甘草石膏汤","疏凿饮子","防风通圣散","五积散"],"a":2,"e":"疏凿饮子泻下逐水、疏风发表，主治水湿壅盛、表里俱实之遍身水肿、喘呼气急、烦躁口渴、二便不利、脉沉实，方以商陆、泽泻通利二便，羌活、秦艽疏表。五积散主外寒内湿证。"},{"q":"患者少腹拘急，小便自利，谵语烦渴，至夜发热，舌面瘀点，脉涩。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":2,"e":"桃核承气汤泻热逐瘀，主治下焦蓄血证，见少腹拘急、小便自利、谵语烦渴、至夜发热、舌有瘀点、脉涩，方以桃仁、大黄、桂枝逐瘀泻热。血府逐瘀汤主胸中血瘀，病位不同。"},{"q":"患者胁肋疼痛，嘈杂吞酸，呕吐口苦，舌红苔黄，脉弦数。治疗应首选的方剂是","o":["左金丸","凉膈散","逍遥散","龙胆泻肝汤","黄连解毒汤"],"a":0,"e":"左金丸清泻肝火、降逆止呕，主治肝火犯胃之胁肋疼痛、嘈杂吞酸、呕吐口苦、舌红苔黄、脉弦数，方中黄连与吴茱萸用量六比一，辛开苦降。龙胆泻肝汤主肝胆实火湿热俱盛。"},{"q":"患者神昏谵语，身热烦躁，喉中痰鸣，气息粗大，舌绛苔黄垢腻，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":2,"e":"至宝丹清热开窍、化浊解毒，主治痰热内闭心包，见神昏谵语、身热烦躁、喉中痰鸣、气息粗大、舌绛苔黄垢腻。安宫牛黄丸长于清热解毒，紫雪长于熄风止痉，三者主治各有偏重。"},{"q":"患者，女。平素月经滞后，行经时小腹疼痛，喜温喜按，入冬后手足生冻疮，肢冷畏寒，舌淡苔薄白，脉细迟。治宜选用","o":["四物汤","当归四逆汤","黄土汤","理中丸","小建中汤"],"a":1,"e":"当归四逆汤温经散寒、养血通脉，主治血虚寒厥，见手足厥寒、脉细欲绝，亦治寒入经络之腰腿疼痛与冻疮；经行腹痛喜温、肢冷畏寒、脉细迟正合其证。四物汤养血而无温通之力。"},{"q":"胁肋疼痛，吞酸吐苦，舌红少津，脉虚弦，治宜选用","o":["逍遥丸","四逆散","龙胆泻肝汤","小柴胡汤","一贯煎"],"a":4,"e":"一贯煎滋阴疏肝，主治肝肾阴虚、肝气不舒，见胁肋疼痛、吞酸吐苦、咽干口燥、舌红少津、脉虚弦。逍遥散主肝郁血虚脾弱，龙胆泻肝汤主肝胆实火湿热。"},{"q":"患者，男，47岁。头晕眼花，站立不稳，重者如乘船晕车，颈项僵硬不适。时伴恶心，呕吐，自觉胸闷，乏力，二便尚可，舌淡、体微胖边有齿痕、苔白，脉弦滑。治疗宜选的方剂是","o":["半夏白术天麻汤","镇肝熄风汤加钩藤、石决明、葛根","天麻钩藤饮加白术、葛根","天麻钩藤饮","半夏白术天麻汤加钩藤、石决明、葛根"],"a":4,"e":"半夏白术天麻汤化痰熄风，眩晕如乘舟车、胸闷乏力、舌淡体胖有齿痕、苔白、脉弦滑属风痰上扰；颈项僵硬为风痰阻络、经气不利，故加钩藤、石决明平肝潜阳，葛根解肌舒筋。"},{"q":"患者咳嗽，痰稠，痰中带血，咯吐不爽，心烦易怒，胸胁作痛，舌红苔黄，脉弦数，治宜选用","o":["咳血方","清气化痰丸","清燥救肺汤","泻白散","百合固金汤"],"a":0,"e":"咳血方清肝宁肺、凉血止血，主治肝火犯肺之咳血，见咳嗽痰稠带血、咯吐不爽、心烦易怒、胸胁作痛、舌红苔黄、脉弦数。百合固金汤主肺肾阴虚之痰中带血，无肝火见证。"},{"q":"患者小肠疝气，少腹痛引睾丸，舌淡，苔白，脉沉弦，宜用","o":["橘核丸","天台乌药散","吴茱萸汤","暖肝煎","枳实薤白桂枝汤"],"a":1,"e":"天台乌药散行气疏肝、散寒止痛，主治寒凝肝脉之小肠疝气，见少腹痛引睾丸、舌淡苔白、脉沉弦。橘核丸主寒湿疝气之坚硬如石，暖肝煎主肝肾虚寒之疝气而兼虚象。"},{"q":"症见胆怯易惊，头眩心悸，心烦不眠，呕吐呃逆，癫痫，舌苔白腻，脉弦滑者。治宜选用","o":["温胆汤","清气化痰丸","定痫丸","酸枣仁汤","滚痰丸"],"a":0,"e":"温胆汤理气化痰、和胃利胆，主治胆胃不和、痰热内扰，见胆怯易惊、头眩心悸、心烦不眠、呕吐呃逆，或发癫痫，舌苔白腻、脉弦滑。酸枣仁汤主肝血不足之虚烦不眠，无痰浊之象。"},{"q":"患者，三焦火毒热盛而见发斑，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["清营汤","黄芩汤","犀角地黄汤","清瘟败毒饮","黄连解毒汤"],"a":4,"e":"黄连解毒汤泻火解毒，主治三焦火毒热盛，见大热烦躁、口燥咽干、错语不眠，或吐衄发斑、舌红苔黄、脉数有力。犀角地黄汤主热入血分之耗血动血，清营汤主热入营分。"},{"q":"患者心悸怔忡，失眠多梦，急躁易怒，入暮潮热，唇黯，舌黯红，脉紧涩。治疗应首选的方剂是","o":["失笑散","血府逐瘀汤","桃核承气汤","复元活血汤","生化汤"],"a":1,"e":"血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀，见心悸怔忡、失眠多梦、急躁易怒、入暮潮热、唇黯、舌黯红、脉涩，方中柴胡、枳壳升降气机。桃核承气汤主下焦蓄血。"},{"q":"患者呃逆不已，胸脘痞闷，舌淡苔白，脉沉迟，宜用","o":["橘皮竹茹汤","丁香柿蒂汤","旋覆代赭汤","藿香正气散","六君子汤"],"a":1,"e":"丁香柿蒂汤温中益气、降逆止呃，主治胃气虚寒之虚寒呃逆，见呃逆不已、胸脘痞闷、舌淡苔白、脉沉迟。橘皮竹茹汤主胃虚有热之呃逆，旋覆代赭汤主胃虚痰阻之噫气不除。"},{"q":"患者胁腹痞满，大便秘结，纳食减少，舌苔薄腻，脉弦，宜用","o":["五磨饮子","六磨饮子","枳实消痞丸","四磨汤","香砂六君子汤"],"a":1,"e":"六磨饮子行气降逆、通腑导滞，主治气滞便秘，见胁腹痞满、大便秘结、纳食减少、苔薄腻、脉弦，方中木香、沉香、槟榔顺气破结。五磨饮子专主气厥实证而无通便之力。"},{"q":"患者男，50岁，恶寒发热伴水肿1周，西医诊断急性肾小球肾炎，现身体疼痛，无汗，舌苔薄白，脉浮紧。可用下列何方加味治疗","o":["桂枝汤","麻黄汤","败毒散","大青龙汤","小青龙汤"],"a":1,"e":"麻黄汤发汗解表、宣肺平喘，外感风寒表实证兼水肿者可用其宣肺以通调水道，见恶寒发热、身痛无汗、苔薄白、脉浮紧。大青龙汤证当兼烦躁，小青龙汤证当有寒饮喘咳。"},{"q":"患者痛经，月经前少腹胀痛，胀甚于痛，连及胸胁、乳房胀痛，舌淡，苔薄白，脉弦紧，宜用","o":["橘核丸","天台乌药散","加味乌药汤","暖肝煎","枳实薤白桂枝汤"],"a":2,"e":"加味乌药汤行气活血、调经止痛，主治气滞血瘀之痛经，见经前少腹胀痛、胀甚于痛、连及胸胁乳房胀痛、苔薄白、脉弦。天台乌药散主寒凝肝脉之疝气，病位与主症不同。"},{"q":"以恶寒发热，无汗，喘咳，痰多而稀，舌苔白滑，脉浮为辨证要点的方剂是","o":["葱豉桔梗汤","香苏散","败毒散","九味羌活汤","小青龙汤"],"a":4,"e":"小青龙汤解表散寒、温肺化饮，辨证要点为恶寒发热、无汗、喘咳、痰多而稀、舌苔白滑、脉浮。九味羌活汤兼口苦微渴之里热，香苏散主胸脘痞闷之气滞，败毒散主气虚外感。"},{"q":"患者胃火牙痛。治疗应首选的方剂是","o":["玉女煎","左金丸","清胃散","白虎汤","凉膈散"],"a":2,"e":"清胃散清胃凉血，主治胃火循经上攻之牙痛，见牙痛牵引头痛、面颊发热、其齿喜冷恶热、舌红苔黄、脉滑数，方中黄连配升麻清胃火而散郁热。玉女煎主胃热阴虚之牙痛。"},{"q":"患者暴饮暴食之后，又复受凉，淬然心腹胀痛，痛如锥刺，气急口噤，大便不通。宜选用的方剂是","o":["大陷胸汤","大承气汤","温脾汤","大黄附子汤","三物备急丸"],"a":4,"e":"三物备急丸攻逐寒积，主治寒实冷积卒起，见猝然心腹胀痛、痛如锥刺、气急口噤、大便不通，方中巴豆辛热峻下，干姜温中，大黄泻下。温脾汤主脾阳不足之冷积而虚实并见。"},{"q":"患者，女，60岁。腹痛便秘，畏寒肢冷，手足不温，苔白腻，脉弦紧。医生用大黄附子汤治疗，方中的君药是","o":["干姜","大黄","附子","细辛","人参"],"a":2,"e":"大黄附子汤温里散寒、通便止痛，方中附子温阳散寒为君，大黄泻下通便为臣，细辛温散寒邪为佐，属温下之剂，主治寒积里实之腹痛便秘、畏寒肢冷、苔白腻、脉弦紧。"},{"q":"患者发热，恶寒甚剧，其寒不解，神疲欲寐，脉沉微。治疗应首选的方剂是","o":["四逆汤","回阳救急汤","再造散","参附汤","麻黄附子细辛汤"],"a":4,"e":"麻黄附子细辛汤助阳解表，主治素体阳虚、外感风寒，见恶寒甚剧、发热、其寒不解、神疲欲寐、脉沉微。再造散主阳气虚弱外感而兼气虚，四逆汤为少阴亡阳之回阳救逆方。"},{"q":"配伍特点为重用甘寒，补中寓清；心肾并治，重在养心的方剂是","o":["朱砂安神丸","桂枝甘草龙骨牡蛎汤","天王补心丹","酸枣仁汤","甘麦大枣汤"],"a":2,"e":"天王补心丹滋阴清热、养血安神，配伍特点是重用生地黄等甘寒之品滋阴养血，补中寓清，心肾并治而重在养心，主治阴虚血少、神志不安之心悸失眠、健忘梦遗、口舌生疮。"},{"q":"患者咳嗽气喘，呼多吸少，声音低怯，痰稠色黄，或咳吐脓血，胸中烦热，身体羸瘦，或遍身浮肿，脉浮虚，治疗宜用的方剂是","o":["异功散","胶艾汤","玉屏风散","生脉散","人参蛤蚧散"],"a":4,"e":"人参蛤蚧散补肺益肾、止咳定喘，主治肺肾气虚、痰热内蕴之久咳气喘，见呼多吸少、声音低怯、痰稠色黄或咳吐脓血、胸中烦热、身体羸瘦。生脉散益气养阴，无补肺肾定喘之力。"},{"q":"患者，女，31岁。因洗澡后受凉3天，现咳嗽，口渴，脉浮数。可用以下何方加减治疗","o":["银翘散","升麻葛根汤","麻黄杏仁甘草石膏汤","柴葛解肌汤","桑菊饮"],"a":4,"e":"桑菊饮疏风清热、宣肺止咳，主治风温初起、表热轻证，见咳嗽、身热不甚、口微渴、脉浮数。银翘散为辛凉平剂，以发热重、咽痛口渴为主；麻杏甘石汤证当见喘咳、苔黄。"},{"q":"患者大便不通6天，兼见频转矢气，脘腹痞满，腹痛拒按，手足濈然汗出，舌苔黄燥，脉沉实。医生主张用“釜底抽薪，急下存阴”治法，方剂是","o":["大陷胸汤","大承气汤","十枣汤","麻子仁丸","三物备急丸"],"a":1,"e":"大承气汤峻下热结，主治阳明腑实证痞满燥实俱备，见大便不通、频转矢气、脘腹痞满、腹痛拒按、手足濈然汗出、苔黄燥、脉沉实，急下存阴即釜底抽薪之法。"},{"q":"患者半身不遂，口眼歪斜，口角流涎，遗尿失禁，舌黯淡，苔白，脉缓无力。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":1,"e":"补阳还五汤补气活血通络，主治气虚血瘀之中风后遗，见半身不遂、口眼歪斜、口角流涎、遗尿失禁、舌黯淡、苔白、脉缓无力，方中重用黄芪补气以行血。血府逐瘀汤主胸中血瘀。"},{"q":"患者，三焦火毒热盛而见吐血、衄血，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["黄连解毒汤","犀角地黄汤","清瘟败毒饮","普济消毒饮","仙方活命饮"],"a":0,"e":"黄连解毒汤泻火解毒，主治三焦火毒热盛之吐血、衄血，见舌红苔黄、脉数有力，方中黄连泻中焦之火，黄芩泻上焦，黄柏泻下焦，栀子通泻三焦。犀角地黄汤主热入血分之动血。"},{"q":"患者胃脘灼热隐痛，饥不欲食，口干咽燥，大便干结，舌红少津，脉细数。治疗宜首选的方剂是","o":["麦门冬汤","益胃汤","养阴清肺汤","清燥救肺汤","玉液汤"],"a":1,"e":"益胃汤养阴益胃，主治胃阴不足，见胃脘灼热隐痛、饥不欲食、口干咽燥、大便干结、舌红少津、脉细数。麦门冬汤主虚热肺痿及胃阴不足之呕吐，兼有气逆之候。"},{"q":"患者痰涎壅盛，喉中痰声辘辘，气闭不通，心神瞀闷，四肢不收，或倒仆不省，或口角似㖞，脉滑实有力。治疗应首选的方剂是","o":["二陈汤","救急稀涎散","镇肝熄风汤","羚角钩藤汤","大承气汤"],"a":1,"e":"救急稀涎散涌吐痰涎、开关通窍，主治中风闭证痰涎壅盛，见喉中痰声辘辘、气闭不通、心神瞀闷、四肢不收、倒仆不省、脉滑实有力，取其吐去痰涎以通窍。二陈汤力缓不能救急。"},{"q":"患者高热不退，烦闷躁扰，手足抽搐，发为痉厥，甚则神昏，舌质绛而干，或舌焦起刺，脉弦数。治疗首选的方剂是","o":["天麻钩藤饮","镇肝熄风汤","羚角钩藤汤","大定风珠","大秦艽汤"],"a":2,"e":"羚角钩藤汤凉肝熄风、增液舒筋，主治肝经热盛、热极动风，见高热不退、烦闷躁扰、手足抽搐、发为痉厥神昏、舌绛而干、脉弦数。大定风珠主阴虚风动，热势不显而时时欲脱。"},{"q":"患者浮肿身半以下为甚，胸腹胀满，平素带下量多色白、稍稠，舌淡苔白腻，脉沉迟。治疗应首选的方剂是","o":["苓桂术甘汤","五苓散","猪苓汤","真武汤","实脾散"],"a":4,"e":"实脾散温阳健脾、行气利水，主治脾肾阳虚、水气内停之阴水，见身半以下肿甚、胸腹胀满、手足不温、口不渴、舌淡苔白腻、脉沉迟。真武汤证以心悸、瞤动、四肢沉重为主。"},{"q":"患者牙痛牵引头痛，面颊发热，其齿喜冷恶热，舌红苔黄，脉滑数。治疗应首选的方剂是","o":["左金丸","清胃散","玉女煎","普济消毒饮","清瘟败毒饮"],"a":1,"e":"清胃散清胃凉血，主治胃火牙痛，见牙痛牵引头痛、面颊发热、其齿喜冷恶热、或牙宣出血、舌红苔黄、脉滑数，方中升麻为阳明引经药兼散火郁。玉女煎主胃热阴虚之牙痛齿衄。"},{"q":"患者，女，67岁。右上肺癌术后1年余。现咳嗽痰多，呈白色泡沫状，胸闷气短，双侧胸背持续性隐痛，以右侧为甚，舌淡苔白滑，脉弦滑。治疗应首选的方剂是","o":["苏子降气汤","小青龙汤","贝母瓜蒌散","苓甘五味姜辛汤","百合固金汤"],"a":3,"e":"苓甘五味姜辛汤温肺化饮，主治寒饮咳嗽，见咳嗽痰多、清稀色白、胸满、舌淡苔白滑、脉弦滑，方中干姜、细辛、五味子温散与收敛并用。小青龙汤证当兼恶寒发热之表寒。"},{"q":"患者大便秘结，脘腹胀满，腹痛拒按，身热口渴，神倦少气，谵语，神昏肢厥，舌苔焦黑，脉虚。治疗应首选方剂是","o":["大承气汤","小承气汤","黄龙汤","安宫牛黄丸","至宝丹"],"a":2,"e":"黄龙汤攻下通便、补气养血，主治阳明腑实而气血不足，见大便秘结、脘腹胀满、腹痛拒按、身热口渴、神倦少气、谵语，甚则神昏肢厥、苔焦黑、脉虚。大承气汤证纯实无虚。"},{"q":"患者婚后久不孕育，全身痩削，阳痿遗精，两目昏花，腰膝酸软，治疗宜用的方剂是","o":["左归丸","肾气丸","右归丸","龟鹿二仙胶","六味地黄丸"],"a":3,"e":"龟鹿二仙胶滋阴填精、益气壮阳，主治真元虚损、精血不足，见久不孕育、全身瘦削、阳痿遗精、两目昏花、腰膝酸软。左归丸偏滋肾阴，右归丸偏温肾阳，肾气丸主肾阳不足。"},{"q":"患者突然鼻衄，血色鲜红，舌红，脉数，治宜选用","o":["咳血方","十灰散","槐花散","小蓟饮子","导赤散"],"a":1,"e":"十灰散凉血止血，主治血热妄行之上部出血，见呕血、吐血、咯血、嗽血、衄血，血色鲜红、舌红脉数，方中十药炒炭存性以增强收涩止血之力。咳血方主肝火犯肺之咳血。"},{"q":"患者恶寒发热，无汗，头痛项强，肢体酸楚疼痛，口苦微渴，舌苔微黄，脉浮紧。治疗应首选的方剂是","o":["桂枝汤","小青龙汤","大青龙汤","败毒散","九味羌活汤"],"a":4,"e":"九味羌活汤发汗祛湿、兼清里热，主治外感风寒湿邪、内有蕴热，见恶寒发热、无汗、头痛项强、肢体酸楚疼痛、口苦微渴、苔微黄、脉浮紧。大青龙汤证以不汗出而烦躁为主。"},{"q":"患者小便不利，身热心烦，口渴欲饮，舌红苔微黄，脉细数。治疗应首选的方剂是","o":["蒿芩清胆汤","真武汤","五苓散","六一散","猪苓汤"],"a":4,"e":"猪苓汤利水、养阴、清热，主治水热互结伤阴，见小便不利、发热口渴欲饮、心烦不寐、舌红苔白或微黄、脉细数。五苓散证为膀胱气化不利之蓄水，无阴虚内热之象。"},{"q":"以心悸失眠，体倦食少，便血或崩漏，舌淡，脉细弱为证治要点的方剂是","o":["补中益气汤","归脾汤","四物汤","胶艾汤","当归补血汤"],"a":1,"e":"归脾汤益气补血、健脾养心，主治心脾气血两虚及脾不统血，证治要点为心悸失眠、体倦食少、便血或崩漏、舌淡、脉细弱，方中黄芪、龙眼肉补脾养心。四物汤专主血虚。"},{"q":"患者头晕目眩，目胀耳鸣，脑部热痛，面色如醉，心中烦热，或时常噫气，或肢体渐觉不利，口眼渐形斜；甚或眩晕颠仆，昏不知人，移时始醒；或醒后不能复原，脉弦长有力。治疗首选的方剂是","o":["大秦艽汤","天麻钩藤饮","羚角钩藤汤","大定风珠","镇肝熄风汤"],"a":4,"e":"镇肝熄风汤镇肝熄风、滋阴潜阳，主治肝肾阴虚、肝阳偏亢、气血逆乱之类中风，见头目眩晕、目胀耳鸣、脑部热痛、面色如醉、心中烦热、肢体渐觉不利、脉弦长有力。"},{"q":"患者壮热面赤，烦渴引饮，汗出恶热，脉洪大有力。治疗应首选的方剂是","o":["败毒散","白虎汤","银翘散","黄连解毒汤","甘露消毒丹"],"a":1,"e":"白虎汤清热生津，主治阳明气分热盛，见壮热面赤、烦渴引饮、汗出恶热、脉洪大有力，即四大症俱备。白虎加人参汤证当兼背微恶寒、脉大而芤之气津两伤。"},{"q":"患者上吐下泻，胸脘痞闷，舌苔黄腻，脉濡数。治疗应首选的治法是","o":["利水渗湿，理气和中","清热解毒，理气和中","利湿化浊，理气和中","清热化湿，理气和中","清热泻火，理气和中"],"a":3,"e":"上吐下泻、胸脘痞闷、苔黄腻、脉濡数，为湿热蕴阻中焦、升降失常之湿热霍乱，治当清热化湿、理气和中，连朴饮为代表方。单纯利湿化浊者适用于寒湿霍乱之湿邪偏重。"},{"q":"以发热，微恶寒，咽痛，口渴，脉浮数为辨证要点的方剂是","o":["银翘散","柴葛解肌汤","麻黄杏仁甘草石膏汤","桑菊饮","升麻葛根汤"],"a":0,"e":"银翘散辛凉透表、清热解毒，为辛凉平剂，主治温病初起，辨证要点为发热、微恶寒、咽痛、口渴、脉浮数。桑菊饮为辛凉轻剂以咳嗽为主，柴葛解肌汤主三阳合病之表里同病。"},{"q":"患者疹发不出，身热头痛，咳嗽，目赤流泪，口渴，舌红，苔薄而干，脉浮数。治疗宜首选的方剂是","o":["柴葛解肌汤","银翘散","升麻葛根汤","桑菊饮","麻黄杏仁甘草石膏汤"],"a":2,"e":"升麻葛根汤解肌透疹，主治麻疹初起、疹发不出或出而不畅，见身热头痛、咳嗽、目赤流泪、口渴、舌红苔薄而干、脉浮数，方中升麻、葛根透疹解毒。银翘散主风热表证而无透疹专功。"},{"q":"患者骨蒸潮热，肌肉消瘦，唇红颊赤，气粗困倦，舌红少苔，脉细数。治疗应首选的方剂是","o":["清骨散","凉膈散","六味地黄丸","知柏地黄丸","秦艽鳖甲散"],"a":4,"e":"秦艽鳖甲散滋阴养血、清热除蒸，主治风劳病，见骨蒸潮热、肌肉消瘦、唇红颊赤、气粗困倦、舌红少苔、脉细数，方中鳖甲、知母滋阴退热，秦艽、柴胡透肌解热。清骨散主虚劳骨蒸而无风邪。"},{"q":"患者心下痞鞕，噫气不除，舌质淡，苔白滑，脉弦而虚，宜用","o":["六君子汤","半夏泻心汤","枳实消痞丸","旋覆代赭汤","丁香柿蒂汤"],"a":3,"e":"旋覆代赭汤降逆化痰、益气和胃，主治胃虚痰阻气逆，见心下痞硬、噫气不除、舌淡苔白滑、脉弦而虚，方中重用生姜，代赭石质重沉降。半夏泻心汤主寒热互结之心下痞而无噫气不除。"},{"q":"据“疗寒以热，而佐以寒”而用之寒药属于","o":["君药","佐药","引经药","臣药","调和药"],"a":1,"e":"反佐即“疗寒以热而佐以寒”，于温热剂中少佐寒凉药，取其同气相求、引药入病所并防格拒，此类寒药属佐药。臣药辅助君药主病，引经药引诸药直达病所，均非此义。"},{"q":"患者小便频数，小腹急满，溺时涩痛，尿色浑赤，淋沥不畅，甚则癃闭不通，口燥咽干，舌苔黄腻，脉滑数。治疗应首选的治法是","o":["清热化瘀，利水通淋","清热解暑，利水通淋","清热排石，利水通淋","清热泻火，利水通淋","清热凉血，利水通淋"],"a":3,"e":"小便频数涩痛、尿色浑赤、淋沥不畅、苔黄腻、脉滑数，为湿热下注膀胱之热淋，治当清热泻火、利水通淋，八正散为代表方，木通、车前子、萹蓄、瞿麦通利水道，栀子、大黄泻火。"},{"q":"患者热入血分证而见便血，喜忘如狂，漱水不欲咽，舌深绛起刺，脉数。治疗应首选的方剂是","o":["普济消毒饮","清瘟败毒饮","犀角地黄汤","青蒿鳖甲汤","黄连解毒汤"],"a":2,"e":"犀角地黄汤清热解毒、凉血散瘀，主治热入血分证，见便血、喜忘如狂、漱水不欲咽、舌深绛起刺、脉数。黄连解毒汤主三焦火毒之实热，清营汤主热入营分之身热夜甚、时有谵语。"},{"q":"患者消化不良，面黄形瘦，肚腹胀大，口臭发热，舌苔黄腻。治疗应首选的方剂是","o":["保和丸","健脾丸","枳实导滞丸","乌梅丸","肥儿丸"],"a":4,"e":"肥儿丸杀虫消积、健脾清热，主治小儿虫积、脾虚胃热，见消化不良、面黄形瘦、肚腹胀大、口臭发热、舌苔黄腻。健脾丸主脾虚食积而无虫积，保和丸主食积停滞之轻证。"},{"q":"患者长期从事鱼丸制作工作，每年秋冬季节出现双手诸关节疼痛，屈伸不利，畏寒喜暖，舌淡苔白，脉细弱。治疗应首选的方剂是","o":["独活寄生汤","羌活胜湿汤","肾著汤","大秦艽汤","九味羌活汤"],"a":0,"e":"独活寄生汤祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚、气血不足，见关节疼痛、屈伸不利、畏寒喜暖、舌淡苔白、脉细弱，方中独活为治下焦风湿之要药。"},{"q":"患者咽中如有物阻，咯吐不出，吞咽不下，舌苔白腻，脉弦滑，宜选用","o":["二陈汤","平胃散","瓜蒌薤白白酒汤","半夏泻心汤","半夏厚朴汤"],"a":4,"e":"半夏厚朴汤行气散结、降逆化痰，主治梅核气，见咽中如有物阻、咯吐不出、吞咽不下、胸膈满闷、苔白腻、脉弦滑，方中半夏、厚朴化痰降逆，紫苏、茯苓理气。二陈汤主湿痰咳嗽。"},{"q":"患者身热，下利臭秽，胸脘烦热，口干作渴，喘而汗出，舌红苔黄，脉数。治疗应首选的方剂是","o":["败毒散","大承气汤","芍药汤","香薷散","葛根黄芩黄连汤"],"a":4,"e":"葛根黄芩黄连汤解表清里，主治表证未解、邪热入里之协热下利，见身热下利、胸脘烦热、口干作渴、喘而汗出、舌红苔黄、脉数，方中重用葛根升阳止利。芍药汤主湿热痢之便脓血。"},{"q":"患者瘿瘤肿硬，皮色不变。首选治疗方剂是","o":["仙方活命饮","阳和汤","大黄牡丹汤","海藻玉壶汤","苇茎汤"],"a":3,"e":"海藻玉壶汤化痰软坚、消瘿散结，主治气滞痰凝之瘿瘤，见瘿瘤肿硬、皮色不变，方中海藻、昆布、海带软坚消瘿。阳和汤温阳补血、散寒通滞，主阴疽漫肿无头而属虚寒者。"},{"q":"跌打损伤，瘀留腋下，痛不可忍，治宜选方","o":["血府逐瘀汤","桃红四物汤","温经汤","复元活血汤","柴胡疏肝散"],"a":3,"e":"复元活血汤活血祛瘀、疏肝通络，主治跌打损伤、瘀血留于胁下而痛不可忍，方中重用大黄荡涤留瘀败血，柴胡疏肝并引药入胁。血府逐瘀汤主胸中血瘀之胸痛，病位不同。"},{"q":"患者心下至少腹硬满疼痛而痛不可近，大便秘结，日晡潮热，舌燥而渴，脉沉紧，按之有力。医生开出的方剂是大陷胸汤，下列煎服法不正确的是","o":["芒硝溶服","冲服甘遂末","水煎服","先煮大黄","清晨空腹服"],"a":4,"e":"大陷胸汤泻热逐水，服法为先煮大黄、去滓内芒硝溶化，冲服甘遂末，温服得快利即止后服，不用清晨空腹服。清晨空腹服为十枣汤等攻下逐水剂之服法，二者不可混同。"},{"q":"患者，男，21岁。脑外伤3个月后，突然摔倒伴四肢抽搐，口吐白沫，意识不清，醒后头晕，乏力。现症见急躁易怒，夜寐多梦，脘胀纳减，痰多色黄，舌质晦红，苔白厚腻，脉弦滑。治疗应首选","o":["血府逐瘀汤加减","半夏白术天麻汤加减","定痫丸加减","天麻钩藤饮加减","镇肝熄风汤加减"],"a":2,"e":"定痫丸涤痰熄风、开窍定痫，主治痰热痫证，见突然昏倒、不省人事、牙关紧闭、肢体抽搐、口吐涎沫、舌苔白腻微黄、脉弦滑，本例脑外伤后痫发兼痰热，故以之加减。"},{"q":"患者，男，44岁。脘腹拘急时痛，喜温喜按3年余，面色无华，神疲乏力，心悸气短，手足烦热，咽干口燥，舌淡苔白，脉弦细。宜选择下列哪方治疗","o":["吴茱萸汤","小建中汤","当归四逆汤","四逆汤","大建中汤"],"a":1,"e":"小建中汤温中补虚、和里缓急，主治虚劳里急，见脘腹拘急时痛、喜温喜按、面色无华、心悸气短、手足烦热、咽干口燥、舌淡苔白、脉弦细，方中重用饴糖建中而缓急止痛。"},{"q":"患者疮疡初起，红肿焮痛，身热凛寒，苔薄白，脉数有力。首选治疗方剂是","o":["五味消毒饮","仙方活命饮","黄连解毒汤","四妙勇安汤","普济消毒饮"],"a":1,"e":"仙方活命饮清热解毒、消肿溃坚、活血止痛，为“疮疡之圣药”，主治痈疡初起、热毒壅聚，见红肿焮痛、身热凛寒、苔薄白、脉数有力。五味消毒饮专主疔毒，普济消毒饮主大头瘟。"},{"q":"以恶寒发热，头痛无汗，胸脘痞闷，苔薄白，脉浮为辨证要点的方剂是","o":["葱豉桔梗汤","败毒散","九味羌活汤","小青龙汤","香苏散"],"a":4,"e":"香苏散理气解表，主治外感风寒、气滞不舒，辨证要点为恶寒发热、头痛无汗、胸脘痞闷、苔薄白、脉浮。九味羌活汤兼口苦微渴之里热，小青龙汤证当见喘咳痰稀之寒饮。"},{"q":"患者有慢性前列腺炎病史，近期小便混浊，状如膏糊，排尿涩痛，舌淡苔白，脉沉。治疗应首选的方剂是","o":["导赤散","小蓟饮子","萆薢分清饮","八正散","猪苓汤"],"a":2,"e":"萆薢分清饮温肾利湿、分清化浊，主治下焦虚寒之膏淋、白浊，见小便混浊如米泔、排尿涩痛、舌淡苔白、脉沉，方中萆薢利湿化浊，益智仁温肾。八正散主湿热淋证而见苔黄腻。"},{"q":"患者尿频尿急，溺时涩痛，淋沥不畅，舌苔黄腻，脉滑数。治疗应首选的方剂是","o":["石韦散","导赤散","八正散","六一散","小蓟饮子"],"a":2,"e":"八正散清热泻火、利水通淋，主治湿热下注膀胱之热淋、血淋，见尿频尿急、溺时涩痛、淋沥不畅、舌苔黄腻、脉滑数，方中木通、车前子、萹蓄、瞿麦、滑石通利湿热。小蓟饮子偏于凉血止血。"},{"q":"患者往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，口苦，咽干，目眩，舌苔薄白，脉弦。治疗宜首选的方剂是","o":["半夏泻心汤","龙胆泻肝汤","小柴胡汤","参苓白术散","逍遥散"],"a":2,"e":"小柴胡汤和解少阳，主治伤寒少阳证，见往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕、口苦咽干目眩、苔薄白、脉弦，方中柴胡配黄芩和解枢机。半夏泻心汤主寒热互结之心下痞。"},{"q":"孙某，女，50岁。便秘腹痛，绕脐绞痛不止，手足不温，苔白不渴，脉沉弦而迟。医生选用具有攻下冷积、温补脾阳功用的方剂治疗，该方是","o":["温脾汤","大黄附子汤","五仁丸","三物备急丸","麻子仁丸"],"a":0,"e":"温脾汤攻下冷积、温补脾阳，主治脾阳不足、冷积内停，见便秘腹痛、绕脐绞痛、手足不温、苔白不渴、脉沉弦而迟，方中附子、干姜温阳，大黄泻下，人参、甘草益气。大黄附子汤无温补之力。"},{"q":"患者身热多汗，心胸烦闷，气逆欲呕，口干喜饮，虚羸少气，舌红苔少，脉虚数等。治疗应首选的方剂是","o":["白虎汤","竹叶石膏汤","清暑益气汤","白虎加人参汤","白虎加桂枝汤"],"a":1,"e":"竹叶石膏汤清热生津、益气和胃，主治热病之后余热未清、气津两伤，见身热多汗、心胸烦闷、气逆欲呕、口干喜饮、虚羸少气、舌红苔少、脉虚数。白虎汤证为气分热盛而正气未伤。"},{"q":"患者患处漫肿无头，皮色不变，酸痛无热，口中不渴，舌淡苔白，脉沉细。首选治疗方剂是","o":["仙方活命饮","普济消毒饮","阳和汤","大黄牡丹汤","小金丹"],"a":2,"e":"阳和汤温阳补血、散寒通滞，主治阴疽，见患处漫肿无头、皮色不变、酸痛无热、口中不渴、舌淡苔白、脉沉细，方中重用熟地黄温补营血，麻黄、姜炭散寒通滞。仙方活命饮主阳证痈疡。"},{"q":"患者，女，56岁。平素怕风，现感冒1天，症见恶风，发热，体温38、5℃，出汗，头痛，食后欲呕，苔白，脉浮缓。可用下列何方加味治疗","o":["大青龙汤","败毒散","麻黄汤","桂枝汤","小青龙汤"],"a":3,"e":"桂枝汤解肌发表、调和营卫，主治外感风寒表虚证，见恶风发热、汗出头痛、鼻鸣干呕、苔白不渴、脉浮缓，方中桂枝解肌、芍药敛阴，姜枣草调和营卫。麻黄汤证为无汗而喘之表实证。"},{"q":"患者，女。平素月经量少，周期延长，有时四五十天才月经来潮，入冬后，手、足及耳部多处发生冻疮，肢冷畏寒，舌淡苔薄白，脉细迟。治宜选用","o":["四逆汤","四逆散","小建中汤","当归四逆汤","桂枝人参汤"],"a":3,"e":"当归四逆汤温经散寒、养血通脉，主治血虚寒厥，见手足厥冷、脉细欲绝，可伴月经量少后期与寒凝经脉之冻疮；肢冷畏寒、舌淡苔薄白、脉细迟正合其证。四逆汤主少阴阳衰之厥逆。"},{"q":"患者突然昏倒，牙关紧闭，不省人事，苔白脉迟，治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","苏合香丸","抱龙丸","紫金锭"],"a":2,"e":"苏合香丸芳香开窍、行气止痛，主治寒邪秽浊闭阻机窍之寒闭证，见突然昏倒、牙关紧闭、不省人事、苔白脉迟，方中苏合香、麝香、冰片辛温开窍。安宫牛黄丸主热闭，二者寒热迥异。"},{"q":"产后血虚，复感风寒，恶露不行，少腹冷痛，治宜选方","o":["温经汤","四物汤","归脾汤","生化汤","逍遥散"],"a":3,"e":"生化汤养血祛瘀、温经止痛，主治产后血虚寒凝、瘀血内阻，见恶露不行、少腹冷痛，方中重用当归养血，川芎、桃仁活血，炮姜温经。温经汤主冲任虚寒之月经不调，非产后主方。"},{"q":"患者，男，正值夏季高温时节，患暑热病而见身大热属于气津两伤者。治疗应首选的方剂是","o":["白虎加人参汤","竹叶石膏汤","当归六黄汤","清暑益气汤","桂苓甘露饮"],"a":0,"e":"白虎加人参汤清热、益气、生津，主治气分热盛而气津两伤，见身大热、大汗、大渴、脉洪大而芤，暑热耗气伤津者用之。竹叶石膏汤主热病后余热未清，清暑益气汤主暑伤气津而无大热。"},{"q":"患者肢节烦痛，肩背沉得，或脚气肿痛，苔白腻微黄，脉濡数。主治病证是","o":["湿热相搏，外受暑邪证","湿热相搏，外受疫邪证","湿热相搏，外受风邪证","湿热相搏，外受寒邪证","湿热相搏，外受燥邪证"],"a":2,"e":"当归拈痛汤利湿清热、疏风止痛，主治湿热相搏、外受风邪证，见遍身肢节烦痛、肩背沉重、或脚气肿痛、脚膝生疮、苔白腻微黄、脉濡数。羌活胜湿汤证为风湿在表而无湿热之象。"},{"q":"患者素体肺肾阴虚，复感疫毒，出现白喉，宜首选的方剂是","o":["清燥救肺汤","百合固金汤","玉液汤","养阴清肺汤","麦门冬汤"],"a":3,"e":"养阴清肺汤养阴清肺、解毒散疫，主治素体阴虚、复感疫毒之白喉，见喉间起白如腐、咽喉肿痛、鼻干唇燥、脉数。百合固金汤主肺肾阴虚之咳嗽痰血，清燥救肺汤主温燥伤肺。"},{"q":"患者舌强不能言，足废不能用，口干不欲饮，足冷面赤，脉沉细弱，治疗宜用的方剂是","o":["左归丸","右归丸","大补阴丸","肾气丸","地黄饮子"],"a":4,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，主治下元虚衰、痰浊上泛之喑痱，见舌强不能言、足废不能用、口干不欲饮、足冷面赤、脉沉细弱。左归丸、右归丸纯补而无化痰开窍之功。"},{"q":"下列何种病证可使用麻黄汤","o":["尿血而伴恶寒发热无汗，头身疼痛，脉浮紧者","鼻出血而伴恶寒发热无汗，头身疼痛，脉浮紧者","疮疡反复发作伴恶寒发热无汗，头身疼痛，脉浮紧者","咳血而伴恶寒发热无汗，头身疼痛，脉浮紧者","疮疡初起伴恶寒发热无汗，头身疼痛，脉浮紧者"],"a":4,"e":"官方答案为【疮疡初起伴恶寒发热无汗，头身疼痛，脉浮紧者】，但依据教材，正确答案为【鼻出血而伴恶寒发热无汗，头身疼痛，脉浮紧者】。《伤寒论》谓伤寒脉浮紧、不发汗因致衄者麻黄汤主之；疮家虽身疼痛不可发汗，属麻黄汤禁例。"},{"q":"患者心悸不安，痛如针刺而有定处，舌质黯红，脉紧。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":3,"e":"血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀，见心悸不安、痛如针刺而有定处、舌质黯红、脉涩或紧，方中桃仁、红花、川芎活血，柴胡、枳壳理气。失笑散主瘀血停滞之心腹刺痛。"},{"q":"患者三焦火毒热盛证而见有身热下利，舌红苔黄，脉数有力。治疗应首选的方剂是","o":["黄芩汤","小承气汤","普济消毒饮","黄连解毒汤","清瘟败毒饮"],"a":3,"e":"黄连解毒汤泻火解毒，主治三焦火毒热盛而见身热下利、舌红苔黄、脉数有力，方中黄连、黄芩、黄柏分泻三焦之火，栀子导热下行。葛根黄芩黄连汤主表证未解之协热下利。"},{"q":"患者身重肢肿，关节疼痛，汗出恶风，小便不利，苔白脉浮。主治病证是","o":["肺虚之风水","里虚之风水","肾虚之风水","脾虚之风水","表虚之风水"],"a":4,"e":"防己黄芪汤益气祛风、健脾利水，主治表虚不固、水湿内停之风水，见身重肢肿、关节疼痛、汗出恶风、小便不利、苔白脉浮。肾虚、脾虚之水肿当见腰膝酸软或腹胀便溏而无表虚之象。"},{"q":"患者头痛目赤，胁痛，口苦，舌红苔黄，脉弦数有力。治疗应首选的方剂是","o":["凉膈散","银翘散","左金丸","逍遥散","龙胆泻肝汤"],"a":4,"e":"龙胆泻肝汤清泻肝胆实火、清利湿热，主治肝胆实火上炎与肝经湿热下注，见头痛目赤、胁痛口苦、耳聋耳肿、舌红苔黄、脉弦数有力，方中龙胆草为泻肝胆实火之主药。"},{"q":"患者遍身肢节烦痛，肩背沉重，脚膝生疮，苔白腻微黄，脉数。治疗应首选的治法是","o":["利湿清热，疏风止痛","利湿清热，通络止痛","利湿清热，祛瘀止痛","利湿清热，散寒止痛","利湿清热，理气止痛"],"a":0,"e":"当归拈痛汤主治湿热相搏、外受风邪之痹证，治当利湿清热、疏风止痛，方中羌活、防风疏风胜湿，茵陈、猪苓、泽泻利湿清热，苦参、黄芩清热。祛瘀、散寒诸法针对瘀血与寒痹，非本证所宜。"},{"q":"症见月经不调，小腹冷痛，经血夹有瘀块，时有烦热，舌质黯红，脉细涩。治应首选","o":["温经汤","四物汤","归脾汤","生化汤","逍遥散"],"a":0,"e":"温经汤温经散寒、养血祛瘀，主治冲任虚寒、瘀血阻滞，见月经不调、小腹冷痛、经血夹有瘀块、时有烦热、舌质黯红、脉细涩，方中吴茱萸、桂枝温经散寒，当归、川芎养血活血。四物汤无温经之力。"},{"q":"小青龙汤的辨证要点是","o":["恶寒发热，头身疼痛，不汗出而烦躁，脉浮紧","恶风，发热，汗出，脉浮缓","恶寒发热， 无汗而喘，脉浮紧","恶寒发热，头痛无汗，肢体酸楚疼痛，口苦微渴","恶寒发热，无汗，喘咳， 痰多而稀，舌苔白滑，脉浮"],"a":4,"e":"小青龙汤解表散寒、温肺化饮，辨证要点为恶寒发热、无汗、喘咳、痰多而稀、舌苔白滑、脉浮。大青龙汤证为不汗出而烦躁，麻黄汤证为无汗而喘、脉浮紧而无痰饮。"},{"q":"患儿，男，12岁。患癫痫6年。发则突然昏倒，不省人事，面色初潮红，继青紫，甚苍白，牙关紧闭，肢体抽搐，口吐涎沫，并作尖叫，数分钟后苏醒，舌苔白腻微黄，脉弦滑略数。治疗应首选的方剂是","o":["安宫牛黄丸","紫雪","羚角钩藤汤","定痫丸","镇肝熄风汤"],"a":3,"e":"定痫丸涤痰熄风、开窍定痫，主治痰热内蕴之痫证，见突然昏倒、不省人事、牙关紧闭、肢体抽搐、口吐涎沫、舌苔白腻微黄、脉弦滑略数。羚角钩藤汤主热极动风之痉厥而无反复发作之痫证特点。"},{"q":"患者，男，51岁。证见脘腹痞满胀痛，赤白痢疾，里急后重，舌苔黄腻，脉沉实。治宜","o":["保和丸","葛花解酲汤","枳实导滞丸","木香槟榔丸","芍药汤"],"a":3,"e":"木香槟榔丸行气导滞、攻积泄热，主治积滞内停、湿蕴生热，见脘腹痞满胀痛、赤白痢疾、里急后重、舌苔黄腻、脉沉实，方中木香、槟榔、青皮、陈皮行气，大黄、黄连攻积泄热。芍药汤主湿热痢而无积滞胀痛。"},{"q":"患者胸痛，饮水即呛，干呕，易躁易怒，两目黯黑，舌质黯红，舌有瘀斑，脉紧。治疗应首选的方剂是","o":["清营汤","补阳还五汤","桃核承气汤","血府逐瘀汤","清骨散"],"a":3,"e":"血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀，见胸痛、饮水即呛、干呕、易躁易怒、两目黯黑、舌黯红有瘀斑、脉紧，方中桔梗、牛膝一升一降以通胸中气机。"},{"q":"患者久泻不愈，腹痛喜温，腰痠肢冷，神疲乏力，舌淡，苔薄白，脉沉迟无力。治疗首先的方剂是","o":["四神丸","桃花汤","肾气丸","理中丸","真人养脏汤"],"a":0,"e":"四神丸温肾暖脾、固肠止泻，主治脾肾阳虚之肾泄，见久泻不愈、黎明前泻、腹痛喜温、腰酸肢冷、神疲乏力、舌淡苔薄白、脉沉迟无力，方中补骨脂温肾，肉豆蔻、吴茱萸温中。真人养脏汤主滑脱不禁。"},{"q":"以下哪一项不属“七方”的内容","o":["大方","小方","急方","复方","单方"],"a":4,"e":"七方指大方、小方、缓方、急方、奇方、偶方、复方，为《黄帝内经》所立之制方分类，单方不在其列。"},{"q":"患者龚某，腹中时痛，喜温喜按，面色无华，心悸不宁，手足烦热，咽干口燥，舌淡苔白，脉细弦而缓。治宜选用","o":["大建中汤","小建中汤","吴茱萸汤","理中汤","温脾汤"],"a":1,"e":"小建中汤温中补虚、和里缓急，主治虚劳里急，见腹中时痛、喜温喜按、面色无华、心悸不宁、手足烦热、咽干口燥、舌淡苔白、脉细弦而缓，方中重用饴糖甘温建中、缓急止痛。大建中汤主中阳衰弱之腹痛剧烈。"},{"q":"患者大便秘结，口渴，舌干红，脉细数。治疗宜首选的方剂是","o":["增液承气汤","增液汤","调胃承气汤","麻子仁丸","玉液汤"],"a":1,"e":"增液汤滋阴清热、润肠通便，主治阳明温病、津亏肠燥，见大便秘结、口渴、舌干红、脉细数，方中玄参、麦冬、生地增水行舟。增液承气汤兼燥屎内结之痞满，调胃承气汤属攻下之剂。"},{"q":"患者心胸烦热，口渴面赤，意欲冷饮，口舌生疮，舌红脉数。治疗应首选的方剂是","o":["清营汤","败毒散","白虎汤","导赤散","玉女煎"],"a":3,"e":"导赤散清心利水养阴，主治心经火热证，见心胸烦热、口渴面赤、意欲冷饮、口舌生疮、小便赤涩，舌红脉数。黄连解毒汤泻三焦火毒，玉女煎主胃热阴虚，与本证病位不同。"},{"q":"以咳嗽咽痒，微恶风发热，苔薄白为辨证要点的方剂是","o":["九味羌活汤","败毒散","止嗽散","葱豉桔梗汤","香苏散"],"a":2,"e":"止嗽散宣利肺气、疏风止咳，辨证要点为咳嗽咽痒、微恶风发热、苔薄白，药性温润平和，为止嗽化痰之通剂。葱豉桔梗汤主外感风热之头痛身热，九味羌活汤主风寒湿表证。"},{"q":"患者大便秘结，下后两三日，复见便秘，脉沉无力。主治方剂是","o":["小承气汤","调味承气汤","增液汤","增液承气汤","玉液汤"],"a":2,"e":"增液汤滋阴润燥通便，主治津亏肠燥之便秘，见大便秘结、下后两三日复秘、口渴、舌干红、脉沉无力，方中玄参、麦冬、生地滋阴增液以增水行舟。小承气汤证当见痞满实而脉有力。"},{"q":"患者恶风发热，汗出头痛，鼻鸣干呕，苔白不渴，脉浮缓。治疗应首选的方剂是","o":["大青龙汤","桂枝汤","麻黄汤","小青龙汤","败毒散"],"a":1,"e":"桂枝汤解肌发表、调和营卫，主治外感风寒表虚证，见恶风发热、汗出头痛、鼻鸣干呕、苔白不渴、脉浮缓，方中桂枝配芍药调和营卫。麻黄汤证为无汗而喘、脉浮紧之表实证。"},{"q":"患者恶寒发热，脘腹疼痛，呕吐泄泻，舌苔白腻，脉濡。本证的病机是","o":["风寒在表，水饮内停","风寒在表，湿滞脾胃","风寒在表，内有蕴热","风热在表，湿滞脾胃","风湿在表，内有蕴热"],"a":1,"e":"恶寒发热、脘腹疼痛、呕吐泄泻、苔白腻、脉濡，为外感风寒、内伤湿滞之阴暑证，香薷散主之，其病机为风寒在表、湿滞脾胃，方中香薷解表化湿，厚朴、白扁豆行气和中。"},{"q":"患者发烧多日，大便不通，神昏谵语，手足冰凉并有汗出，舌苔黄燥起刺，脉沉实。宜选用的方剂是","o":["四逆散","四逆汤","当归四逆汤","大承气汤","温脾汤"],"a":3,"e":"大承气汤峻下热结，主治阳明腑实证，见发热多日、大便不通、神昏谵语、手足冰凉而汗出、苔黄燥起刺、脉沉实，此为热深厥亦深之热厥，腑实一去则厥自回。四逆汤主少阴阳衰之寒厥。"},{"q":"体虚卫外不固，又复心阳不潜之自汗盗汗，治宜首选","o":["玉屏风散","补中益气汤","四君子汤","牡蛎散","炙甘草汤"],"a":3,"e":"牡蛎散敛阴止汗、益气固表，主治体虚卫外不固、心阳不潜之自汗盗汗，见汗出夜甚、心悸惊惕、短气烦倦、舌淡红、脉细弱，方中牡蛎、麻黄根、浮小麦收敛止汗，黄芪益气固表。"},{"q":"患者心胸刺痛，脘腹疼痛，治宜选方","o":["桃核承气汤","血府逐瘀汤","失笑散","槐花散","导赤散"],"a":2,"e":"失笑散活血祛瘀、散结止痛，主治瘀血停滞之心腹刺痛，见心胸刺痛、脘腹疼痛、痛处固定、舌质紫黯、脉涩，方中五灵脂、蒲黄等分为散，醋调服。血府逐瘀汤主胸中血瘀兼气滞之证。"},{"q":"患者肢节沉重肿痛，苔白腻微黄，脉濡数。治疗应首选的方剂是","o":["羌活胜湿汤","独活寄生汤","当归拈痛汤","五皮散","甘露消毒丹"],"a":2,"e":"当归拈痛汤利湿清热、疏风止痛，主治湿热相搏、外受风邪，见肢节沉重肿痛、肩背沉重、苔白腻微黄、脉濡数，方中羌活、防风疏风，茵陈、苦参、黄芩清热利湿。羌活胜湿汤证无苔黄脉数之热象。"},{"q":"患者呕吐，口渴咽干，舌红少苔，脉虚数。治疗应首选的方剂是","o":["麦门冬汤","琼玉膏","益胃汤","增液汤","玉液汤"],"a":0,"e":"麦门冬汤滋养肺胃、降逆下气，主治胃阴不足、气逆呕吐，见呕吐、口渴咽干、舌红少苔、脉虚数，方中重用麦冬养阴，半夏降逆而用量轻，人参、粳米、甘草益胃。益胃汤主胃阴不足之胃脘灼痛而无呕吐。"},{"q":"症见咳嗽痰多，色白易咳，胸膈痞闷，恶心呕吐，肢体困重，舌苔白滑，脉滑者。治宜选用","o":["茯苓丸","温胆汤","小陷胸汤","二陈汤","苓甘五味姜辛汤"],"a":3,"e":"二陈汤燥湿化痰、理气和中，主治湿痰证，见咳嗽痰多、色白易咳、胸膈痞闷、恶心呕吐、肢体困重、舌苔白滑、脉滑，方中半夏燥湿化痰，陈皮理气，茯苓渗湿。温胆汤证兼痰热而见心烦失眠。"},{"q":"以恶寒重，发热轻，神疲欲寐，脉沉为辨证要点的方剂是","o":["大青龙汤","麻黄附子细辛汤","再造散","败毒散","参苏饮"],"a":1,"e":"麻黄附子细辛汤助阳解表，主治少阴阳虚兼外感风寒，辨证要点为恶寒重、发热轻、神疲欲寐、脉沉。再造散主阳气虚弱外感风寒而兼气虚，参苏饮主气虚外感风寒、内有痰湿。"},{"q":"患者头痛，眩晕，失眠，舌红苔黄，脉弦数。治疗首选的方剂是","o":["半夏白术天麻汤","大定风珠","羚角钩藤汤","天麻钩藤饮","镇肝熄风汤"],"a":3,"e":"天麻钩藤饮平肝熄风、清热活血、补益肝肾，主治肝阳偏亢、肝风上扰，见头痛、眩晕、失眠、舌红苔黄、脉弦数。镇肝熄风汤主肝阳上亢、气血逆乱之类中风，镇肝之力更峻。"},{"q":"患者发热口渴，肢酸倦怠，胸闷腹胀，舌苔白腻，脉滑数。本证的病机是","o":["湿热疫毒，蕴于下焦","湿热疫毒，蕴于中焦","湿热疫毒，蕴于上焦","湿热疫毒，蕴于气分","湿热疫毒，蕴于血分"],"a":3,"e":"发热口渴、肢酸倦怠、胸闷腹胀、舌苔白腻、脉滑数，为湿温时疫、湿热并重、邪在气分之候，甘露消毒丹主之，治当利湿化浊、清热解毒。湿热蕴于下焦者多见小便短赤、淋浊，证候不同。"},{"q":"患者胃气不和，心下痞满不痛，呕吐或肠鸣下利，舌苔腻而微黄。治疗应首选的方剂是","o":["小柴胡汤","痛泻要方","理中丸","半夏泻心汤","芍药汤"],"a":3,"e":"半夏泻心汤寒热平调、散结除痞，主治寒热错杂之痞证，见心下痞满不痛、呕吐或肠鸣下利、舌苔腻而微黄，方中黄连、黄芩苦寒泄热，干姜、半夏辛温散结，人参、大枣、甘草补中。理中丸主虚寒。"}];
